-- ============================================================
-- Dump toàn bộ nội dung khóa "Nền Tảng HSK1-3" (course_id=12) sau khi
-- gộp lại thành 18 module (3 bài/module), bổ sung câu mẫu cho từ vựng,
-- pinyin + giải thích cho ngữ pháp, và bài khóa/câu hỏi đọc hiểu mới
-- (câu hỏi bằng tiếng Trung, hiện luôn không cần bấm "bắt đầu").
-- Thay thế hoàn toàn seed 010/013/015/016 (courses.intro_content.modules
-- + 5 bảng nội dung + reading_passages/comprehension_questions).
-- An toàn khi chạy lại nhiều lần (xóa dữ liệu cũ của course_id=12 trước).
-- Cách chạy: psql -U <user> -d elearning -f 019_hsk_18_modules_full.sql
-- ============================================================

DELETE FROM vocabulary WHERE course_id = 12;
DELETE FROM grammar_patterns WHERE course_id = 12;
DELETE FROM example_sentences WHERE course_id = 12;
DELETE FROM phrases WHERE course_id = 12;
DELETE FROM dialogue_lines WHERE course_id = 12;
DELETE FROM reading_passages WHERE course_id = 12;
DELETE FROM comprehension_questions WHERE course_id = 12;

UPDATE courses SET intro_content = jsonb_set(intro_content, '{modules}', $json$
[{"title":"Module 1","topics":["Xin chào (你好)","Bạn là người nước nào (你是哪国人)","Bạn tên là gì (你叫什么名字)"],"subtitle":"Quyển I - Bài 1-3: Chào hỏi và giới thiệu bản thân"},{"title":"Module 2","topics":["Bạn có học tiếng Pháp không (你学习法语吗)","Nhà bạn có mấy người (你家有几口人)","Chuối bao nhiêu tiền một cân (香蕉多少钱一斤)"],"subtitle":"Quyển I - Bài 4-6: Học tiếng và gia đình"},{"title":"Module 3","topics":["Ngân hàng Trung Quốc ở đâu (中国银行在哪儿)","Hôm nay ngày mấy (今天几号)","Hôm nay bạn có kế hoạch gì (你今天有什么安排)"],"subtitle":"Quyển I - Bài 7-9: Ngân hàng, ngày tháng và kế hoạch"},{"title":"Module 4","topics":["Chủ nhật này bạn có bận không (这个星期天你忙不忙)","Tôi ăn ở căng-tin trường (我在学校食堂吃饭)","Bạn muốn trà hay cà phê (你要茶还是咖啡)"],"subtitle":"Quyển I - Bài 10-12: Cuối tuần, ăn uống và đồ uống"},{"title":"Module 5","topics":["Tôi chuyển nhà rồi (我已经搬家了)","Tôi đã mua một cái áo len (我买了一件毛衣)","Sinh viên có thể đi làm thêm không (大学生可以打工吗)"],"subtitle":"Quyển I - Bài 13-15: Nhà mới, quần áo và làm thêm"},{"title":"Module 6","topics":["Tôi muốn tặng anh ấy một món quà (我想送他一件礼物)","Nói và nghe của tôi đều tốt (我口语和听力都很好)","Tôi lên mạng bốn tiếng (我上了四个小时的网)"],"subtitle":"Quyển I - Bài 16-18: Quà tặng, học tập và Internet"},{"title":"Module 7","topics":["Lò sưởi vẫn chưa sửa xong (暖气还没有修好)","Đồ ăn nhanh có thể giao tận nhà (快餐可以送到家里)","Tôi đã đặt túi lên bàn (我把袋子放在桌子上了)"],"subtitle":"Quyển I - Bài 19-21: Sự cố, đồ ăn giao hàng và đồ đạc"},{"title":"Module 8","topics":["Xe đạp của tôi màu đỏ (我的自行车是红色的)","Mùa đông năm nay lạnh hơn (今年冬天变冷了)","Mẹ gửi quà cho tôi (妈妈给我寄来了礼物)"],"subtitle":"Quyển I - Bài 22-24: Màu sắc, thời tiết và quà từ mẹ"},{"title":"Module 9","topics":["Tôi không hiểu họ nói gì (我听不懂他们说的话)","Giáng sinh sắp đến (圣诞节快到了)","Tôi đang xem TV (我正在看电视呢)"],"subtitle":"Quyển I - Bài 25-27: Ngôn ngữ, lễ hội và giải trí"},{"title":"Module 10","topics":["Vạn Lý Trường Thành dài hơn 8850km (长城有八千八百五十多公里)","Buổi tiệc rất thành công (晚会开得非常成功)","Tôi từng là giáo viên tiếng Anh (我当过英语老师)"],"subtitle":"Quyển I - Bài 28-30: Trường Thành, tiệc tùng và trải nghiệm"},{"title":"Module 11","topics":["Nhập gia tùy tục (入乡随俗)","Con trai muốn về nhà (儿子要回家)","Cô gái bán ớt (卖辣椒的女孩儿)"],"subtitle":"Quyển II - Bài 1-3: Hòa nhập văn hóa mới"},{"title":"Module 12","topics":["Tôi có một cuộc hẹn với Trung Quốc (我和中国有个约会)","Vì sao tôi đứng ăn một mình (为什么我一个人站着吃)","Mọi thứ ở đây đều ổn (我这里一切都好)"],"subtitle":"Quyển II - Bài 4-6: Ước mơ và cuộc sống mới"},{"title":"Module 13","topics":["Tôi sẽ đi Ai Cập (我要去埃及)","Giấc mơ cũ (旧梦)","Giáo dục tình yêu thương (爱的教育)"],"subtitle":"Quyển II - Bài 7-9: Du lịch, ký ức và tình yêu thương"},{"title":"Module 14","topics":["Hạnh phúc thực ra rất đơn giản (快乐，其实很简单)","Con kiến trong sách (书本里的蚂蚁)","Là “gối”, không phải “đầu kim” (是“枕头”，不是“针头”)"],"subtitle":"Quyển II - Bài 10-12: Hạnh phúc và những câu chuyện nhỏ"},{"title":"Module 15","topics":["Lá thư từ Trung Quốc thay đổi cuộc đời tôi (中国来信改变了我的生活)","Lần đầu đi taxi (第一次打的)","Chim bồ câu đưa thư bay về (飞回来的信鸽)"],"subtitle":"Quyển II - Bài 13-15: Thư từ và những chuyến đi"},{"title":"Module 16","topics":["Vặn đồng hồ nhanh ba phút (把表拨快三分钟)","Cuộc hẹn (约会)","Nghe phim (听电影)"],"subtitle":"Quyển II - Bài 16-18: Giờ giấc, hẹn hò và điện ảnh"},{"title":"Module 17","topics":["Bạn qua thư (笔友)","Nhân cách bậc nhất (第一人格)","Ngu Công dời núi (愚公移山)"],"subtitle":"Quyển II - Bài 19-21: Bạn bè, nhân cách và ý chí"},{"title":"Module 18","topics":["Thẻ (卡)","Cuộc sống “ít carbon” của tôi (我的“低碳生活”)","Cha con và Trường Thành (父子长城)","Đi nhờ xe đến Berlin (搭车去柏林)"],"subtitle":"Quyển II - Bài 22-25: Lối sống và những chuyến phiêu lưu"}]
$json$::jsonb) WHERE id = 12;







