INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, example_zh, example_pinyin, example_vi, order_index) VALUES (12, 15, '表', 'biǎo', 'đồng hồ (đeo tay)', 'watch', '他把表拨快三分钟，这样就不会迟到了。', 'Tā bǎ biǎo bō kuài sān fēnzhōng, zhèyàng jiù bú huì chídào le.', 'Anh ấy vặn đồng hồ nhanh lên ba phút, như vậy sẽ không đến muộn.', 0);
