INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, example_zh, example_pinyin, example_vi, order_index) VALUES (12, 15, '盲人', 'mángrén', 'người khiếm thị', 'blind person', '盲人朋友是靠听声音"看"电影的。', 'Mángrén péngyou shì kào tīng shēngyīn "kàn" diànyǐng de.', 'Người bạn khiếm thị ''xem'' phim bằng cách nghe âm thanh.', 21);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, example_zh, example_pinyin, example_vi, order_index) VALUES (12, 15, '即使', 'jíshǐ', 'dù cho', 'even if', '即使看不见画面，他也能想象出情节。', 'Jíshǐ kàn bu jiàn huàmiàn, tā yě néng xiǎngxiàng chū qíngjié.', 'Dù không nhìn thấy hình ảnh, anh ấy vẫn có thể tưởng tượng ra tình tiết.', 22);
