INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, example_zh, example_pinyin, example_vi, order_index) VALUES (12, 17, '陌生人', 'mòshēngrén', 'người lạ', 'stranger', '路上遇到了很多善良的陌生人。', 'Lùshang yùdàole hěn duō shànliáng de mòshēngrén.', 'Trên đường anh ấy gặp rất nhiều người lạ tốt bụng.', 34);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, example_zh, example_pinyin, example_vi, order_index) VALUES (12, 17, '冒险', 'màoxiǎn', 'mạo hiểm', 'adventure, to take risks', '这是一次难忘的冒险经历。', 'Zhè shì yí cì nánwàng de màoxiǎn jīnglì.', 'Đây là một trải nghiệm mạo hiểm khó quên.', 35);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, example_zh, example_pinyin, example_vi, order_index) VALUES (12, 17, '善良', 'shànliáng', 'tốt bụng', 'kind-hearted', '路上遇到了很多善良的陌生人。', 'Lùshang yùdàole hěn duō shànliáng de mòshēngrén.', 'Trên đường anh ấy gặp rất nhiều người lạ tốt bụng.', 36);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, example_zh, example_pinyin, example_vi, order_index) VALUES (12, 17, '顺路', 'shùnlù', 'tiện đường', 'on the way', '现在用卡很方便，不必带很多现金。', 'Xiànzài yòng kǎ hěn fāngbiàn, búbì dài hěn duō xiànjīn.', 'Bây giờ dùng thẻ rất tiện, không cần mang nhiều tiền mặt.', 37);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, example_zh, example_pinyin, example_vi, order_index) VALUES (12, 17, '经历', 'jīnglì', 'trải nghiệm', 'experience', '这是一次难忘的冒险经历。', 'Zhè shì yí cì nánwàng de màoxiǎn jīnglì.', 'Đây là một trải nghiệm mạo hiểm khó quên.', 38);
INSERT INTO vocabulary (course_id, module_index, zh, pinyin, vi, en, example_zh, example_pinyin, example_vi, order_index) VALUES (12, 17, '难忘', 'nánwàng', 'khó quên', 'unforgettable', '这是一次难忘的冒险经历。', 'Zhè shì yí cì nánwàng de màoxiǎn jīnglì.', 'Đây là một trải nghiệm mạo hiểm khó quên.', 39);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 0, '您 - kính ngữ của 你', 'nín hǎo ！ wǒ shì lǐ lǎo shī 。', '您好！我是李老师。', 'Xin chào ạ! Tôi là thầy Lý.', '"您" là cách gọi lịch sự, trang trọng hơn của "你" (bạn). Dùng khi nói với người lớn tuổi, cấp trên, hoặc muốn thể hiện sự tôn trọng — giống như cách người Việt chuyển từ "bạn" sang "anh/chị/ông/bà".', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 0, 'Chào hỏi cơ bản với 你好', 'ā míng ： nǐ hǎo ！   shān tián ： nǐ hǎo ！', '阿明：你好！ 山田：你好！', 'A Minh: Chào bạn! Yamada: Chào bạn!', 'Cấu trúc "Chào hỏi cơ bản với 你好" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "阿明：你好！ 山田：你好！" (A Minh: Chào bạn! Yamada: Chào bạn!).', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 0, 'Trợ từ nghi vấn 呢', 'wǒ shì yuè nán rén ， nǐ ne ？', '我是越南人，你呢？', 'Tôi là người Việt Nam, còn bạn?', '"呢" ở cuối câu dùng để hỏi lại, hỏi tiếp về cùng một chủ đề (giống "còn...thì sao?" trong tiếng Việt), hoặc để hỏi "...đâu rồi?" khi hỏi vị trí. Rất hay dùng sau khi vừa trả lời xong một câu hỏi để hỏi lại người kia.', 2);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 0, 'Hỏi quốc tịch với 是...吗/哪国人', 'nǐ shì nǎ guó rén ？ wǒ shì zhōng guó rén 。', '你是哪国人？我是中国人。', 'Bạn là người nước nào? Tôi là người Trung Quốc.', '"吗" là trợ từ đặt ở CUỐI câu để biến một câu khẳng định thành câu hỏi có/không — giống thêm dấu "?" và ý "có...không" trong tiếng Việt. Không cần đảo trật tự từ, chỉ cần thêm "吗" vào cuối.', 3);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 0, '贵姓 - hỏi họ một cách lịch sự', 'qǐng wèn ， nín guì xìng ？', '请问，您贵姓？', 'Xin hỏi, quý danh của ngài là gì?', '"贵姓" là cách hỏi họ một cách lịch sự (nghĩa đen: "họ quý của bạn"). Câu trả lời thường là "我姓 + họ", không cần nói "贵" khi tự giới thiệu.', 4);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 0, '叫 + tên - giới thiệu tên', 'wǒ jiào zhū yún 。', '我叫朱云。', 'Tôi tên là Chu Vân.', 'Cấu trúc "叫 + tên - giới thiệu tên" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "我叫朱云。" (Tôi tên là Chu Vân.).', 5);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 1, 'Câu vị ngữ động từ', 'wǒ xué xí hàn yǔ 。', '我学习汉语。', 'Tôi học tiếng Hán.', 'Cấu trúc "Câu vị ngữ động từ" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "我学习汉语。" (Tôi học tiếng Hán.).', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 1, 'Câu hỏi với 吗', 'nǐ xué xí fǎ yǔ ma ？', '你学习法语吗？', 'Bạn có học tiếng Pháp không?', '"吗" là trợ từ đặt ở CUỐI câu để biến một câu khẳng định thành câu hỏi có/không — giống thêm dấu "?" và ý "có...không" trong tiếng Việt. Không cần đảo trật tự từ, chỉ cần thêm "吗" vào cuối.', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 1, '几 và 多少 - hỏi số lượng', 'nǐ jiā yǒu jǐ kǒu rén ？', '你家有几口人？', 'Nhà bạn có mấy người?', '"几" dùng khi đoán số lượng nhỏ (dưới 10), phải đi kèm lượng từ (几个, 几口). "多少" dùng cho số lượng bất kỳ (to hay nhỏ đều được) và có thể bỏ lượng từ.', 2);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 1, 'Lượng từ 个 và cách đếm số 1-100', 'wǒ jiā yǒu wǔ gè rén 。', '我家有五个人。', 'Nhà tôi có năm người.', 'Tiếng Trung luôn cần một "lượng từ" đứng giữa số đếm và danh từ (khác tiếng Việt không bắt buộc) — ví dụ "一个人" (một người), "两本书" (hai quyển sách). "个" là lượng từ chung, dùng được cho rất nhiều danh từ khi không chắc dùng lượng từ nào.', 3);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 1, '二 và 两 - phân biệt cách dùng', 'wǒ yǒu liǎng gè gē ge 。', '我有两个哥哥。', 'Tôi có hai anh trai.', '"二" dùng khi đếm số thứ tự hoặc số đơn thuần (số 2). "两" dùng khi đếm SỐ LƯỢNG sự vật, luôn đi kèm lượng từ — ví dụ "两个人" (hai người), không nói "二个人".', 4);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 1, 'Cách đếm số trên 100', 'yì bǎi èr shí kuài', '一百二十块', 'Một trăm hai mươi đồng', 'Cấu trúc "Cách đếm số trên 100" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "一百二十块" (Một trăm hai mươi đồng).', 5);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 1, 'Cách nói tiền tệ (RMB)', 'zhè ge píng guǒ sān kuài qián yì jīn 。', '这个苹果三块钱一斤。', 'Táo này ba đồng một cân.', 'Cấu trúc "Cách nói tiền tệ (RMB)" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "这个苹果三块钱一斤。" (Táo này ba đồng một cân.).', 6);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 1, '...多少钱+一+lượng từ', 'xiāng jiāo duō shǎo qián yì jīn ？', '香蕉多少钱一斤？', 'Chuối bao nhiêu tiền một cân?', 'Tiếng Trung luôn cần một "lượng từ" đứng giữa số đếm và danh từ (khác tiếng Việt không bắt buộc) — ví dụ "一个人" (một người), "两本书" (hai quyển sách). "个" là lượng từ chung, dùng được cho rất nhiều danh từ khi không chắc dùng lượng từ nào.', 7);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 2, 'Câu tồn tại (1)', 'yín háng páng biān yǒu yí gè yī yuàn 。', '银行旁边有一个医院。', 'Bên cạnh ngân hàng có một bệnh viện.', 'Cấu trúc "Câu tồn tại (1)" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "银行旁边有一个医院。" (Bên cạnh ngân hàng có một bệnh viện.).', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 2, '哪儿 và ...在什么地方', 'zhōng guó yín háng zài nǎ ér ？', '中国银行在哪儿？', 'Ngân hàng Trung Quốc ở đâu?', 'Cấu trúc "哪儿 và ...在什么地方" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "中国银行在哪儿？" (Ngân hàng Trung Quốc ở đâu?).', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 2, 'Trợ từ 吧 (1) - đề nghị/phỏng đoán', 'yín háng zài qián biān ba ？', '银行在前边吧？', 'Ngân hàng ở phía trước phải không?', 'Cấu trúc "Trợ từ 吧 (1) - đề nghị/phỏng đoán" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "银行在前边吧？" (Ngân hàng ở phía trước phải không?).', 2);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 2, 'Câu vị ngữ danh từ', 'jīn tiān jiǔ yuè sān hào 。', '今天九月三号。', 'Hôm nay là ngày 3 tháng 9.', 'Cấu trúc "Câu vị ngữ danh từ" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "今天九月三号。" (Hôm nay là ngày 3 tháng 9.).', 3);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 2, 'Cách nói ngày tháng', 'wǒ de shēng rì shì shí èr yuè èr shí hào 。', '我的生日是十二月二十号。', 'Sinh nhật tôi là ngày 20 tháng 12.', 'Cấu trúc "Cách nói ngày tháng" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "我的生日是十二月二十号。" (Sinh nhật tôi là ngày 20 tháng 12.).', 4);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 2, 'Câu hỏi với 对吗?', 'jīn tiān shì xīng qī yī ， duì ma ？', '今天是星期一，对吗？', 'Hôm nay là thứ hai, đúng không?', '"吗" là trợ từ đặt ở CUỐI câu để biến một câu khẳng định thành câu hỏi có/không — giống thêm dấu "?" và ý "có...không" trong tiếng Việt. Không cần đảo trật tự từ, chỉ cần thêm "吗" vào cuối.', 5);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 2, '先...然后... - trước...sau...', 'wǒ xiān shàng kè ， rán hòu qù tú shū guǎn 。', '我先上课，然后去图书馆。', 'Tôi học trước, sau đó đi thư viện.', '"先...然后..." nghĩa là "trước tiên... sau đó...", dùng để kể các hành động theo đúng thứ tự thời gian xảy ra.', 6);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 2, '来/去+(O1)+V+O2', 'wǒ qù tú shū guǎn kàn shū 。', '我去图书馆看书。', 'Tôi đi thư viện đọc sách.', 'Khi câu có cả động từ chính và động từ 来/去 (đến/đi), cấu trúc là: 来/去 + (tân ngữ nơi chốn) + động từ + tân ngữ khác. Ví dụ: 我去图书馆看书 (tôi đi thư viện đọc sách).', 7);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 2, 'Trạng ngữ thời gian', 'wǒ xià wǔ sān diǎn shàng kè 。', '我下午三点上课。', 'Tôi học lúc 3 giờ chiều.', 'Cấu trúc "Trạng ngữ thời gian" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "我下午三点上课。" (Tôi học lúc 3 giờ chiều.).', 8);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 3, 'Câu vị ngữ tính từ', 'wǒ jīn tiān hěn máng 。', '我今天很忙。', 'Hôm nay tôi rất bận.', 'Cấu trúc "Câu vị ngữ tính từ" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "我今天很忙。" (Hôm nay tôi rất bận.).', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 3, 'Câu hỏi chính phản (1)(2)', 'nǐ máng bu máng ？', '你忙不忙？', 'Bạn có bận không?', 'Cấu trúc "Câu hỏi chính phản (1)(2)" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "你忙不忙？" (Bạn có bận không?).', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 3, '一下 - một chút, thử xem', 'nǐ kàn yí xià zhè ge 。', '你看一下这个。', 'Bạn xem thử cái này một chút.', '"一下" đặt sau động từ để làm hành động nghe NHẸ NHÀNG, ngắn gọn hơn — như "thử xem", "một chút", "một lát". Ví dụ: 看一下 (xem thử một chút), 休息一下 (nghỉ một lát).', 2);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 3, 'Trạng ngữ nơi chốn 在+địa điểm', 'wǒ zài xué xiào shí táng chī fàn 。', '我在学校食堂吃饭。', 'Tôi ăn cơm ở căng tin trường.', 'Cấu trúc "Trạng ngữ nơi chốn 在+địa điểm" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "我在学校食堂吃饭。" (Tôi ăn cơm ở căng tin trường.).', 3);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 3, '从...到... - từ...đến...', 'cóng zhè ér dào shí táng hěn jìn 。', '从这儿到食堂很近。', 'Từ đây đến căng tin rất gần.', '"从...到..." nghĩa là "từ... đến...", dùng cho cả thời gian và nơi chốn — ví dụ: 从这儿到食堂 (từ đây đến căng tin), 从九点到十点 (từ 9 giờ đến 10 giờ).', 4);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 3, 'Cách đọc số điện thoại', 'wǒ de diàn huà hào mǎ shì yī sān bā . . .', '我的电话号码是一三八...', 'Số điện thoại của tôi là 138...', 'Cấu trúc "Cách đọc số điện thoại" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "我的电话号码是一三八..." (Số điện thoại của tôi là 138...).', 5);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 3, '对...+V/Adj - đối với...', 'duì wǒ lái shuō ， hē chá bǐ hē kā fēi hǎo 。', '对我来说，喝茶比喝咖啡好。', 'Đối với tôi, uống trà tốt hơn uống cà phê.', '"对...(来说)" nghĩa là "đối với... (mà nói)", dùng để nêu quan điểm/cảm nhận của một ai đó hoặc mức độ ảnh hưởng của việc gì với ai/cái gì đó.', 6);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 3, 'Trợ từ 呢 (2)', 'wǒ yào chá ， nǐ ne ？', '我要茶，你呢？', 'Tôi muốn uống trà, còn bạn?', '"呢" ở cuối câu dùng để hỏi lại, hỏi tiếp về cùng một chủ đề (giống "còn...thì sao?" trong tiếng Việt), hoặc để hỏi "...đâu rồi?" khi hỏi vị trí. Rất hay dùng sau khi vừa trả lời xong một câu hỏi để hỏi lại người kia.', 7);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 3, 'Câu hỏi lựa chọn A还是B', 'nǐ yào chá hái shì kā fēi ？', '你要茶还是咖啡？', 'Bạn muốn trà hay cà phê?', '"A还是B" là câu hỏi LỰA CHỌN giữa hai phương án, dịch là "A hay là B" — khác với "或者" chỉ dùng trong câu khẳng định (không phải câu hỏi).', 8);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 4, 'Phó từ 又 - lại', 'tā jīn tiān yòu chí dào le 。', '他今天又迟到了。', 'Hôm nay anh ấy lại đến muộn.', '"又" nghĩa là "lại" — diễn tả một hành động/sự việc LẶP LẠI đã từng xảy ra trước đó, thường dùng cho việc đã xảy ra rồi (không dùng cho tương lai, tương lai dùng "再").', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 4, 'Trợ từ 了 (1) - hoàn thành', 'wǒ yǐ jīng bān jiā le 。', '我已经搬家了。', 'Tôi đã chuyển nhà rồi.', 'Trợ từ "了" đặt ngay sau động từ để nhấn mạnh một hành động đã HOÀN THÀNH hoặc một sự việc/trạng thái vừa THAY ĐỔI. Đây là một trong những trợ từ quan trọng và hay gây nhầm lẫn nhất với người mới học.', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 4, '怎么 (1) - tại sao', 'nǐ zěn me yòu bān jiā le ？', '你怎么又搬家了？', 'Sao bạn lại chuyển nhà nữa vậy?', '"怎么" dùng để hỏi CÁCH THỨC (làm thế nào) hoặc hỏi LÝ DO (tại sao, thể hiện sự ngạc nhiên) tùy vào ngữ cảnh.', 2);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 4, '一...就... - vừa...thì...', 'tā yí xià kè jiù huí jiā le 。', '他一下课就回家了。', 'Anh ấy vừa tan học liền về nhà.', '"一...就..." nghĩa là "vừa... thì (liền)...", diễn tả hai hành động xảy ra ngay sau nhau, gần như liên tiếp.', 3);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 4, 'Đại từ 这么', 'zhè jiàn máo yī zhè me piào liang ！', '这件毛衣这么漂亮！', 'Áo len này đẹp như vậy!', '"这么" nghĩa là "như thế này", dùng trước tính từ/động từ để nhấn mạnh mức độ — ví dụ: 这么漂亮 (đẹp như thế này).', 4);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 4, 'Phó từ 还 (2) - vẫn còn', 'wǒ hái méi mǎi máo yī 。', '我还没买毛衣。', 'Tôi vẫn chưa mua áo len.', '"还" mang nghĩa "vẫn còn/vẫn đang" khi đứng trước động từ/tính từ, diễn tả một trạng thái tiếp diễn chưa kết thúc.', 5);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 4, 'Trợ động từ 要/可以/能/会', 'dà xué shēng kě yǐ dǎ gōng ma ？', '大学生可以打工吗？', 'Sinh viên đại học có thể đi làm thêm không?', 'Trợ động từ (要/能/会/可以...) luôn đứng TRƯỚC động từ chính để bổ sung nghĩa muốn/có thể/biết làm — khác nhau ở sắc thái: 想/要 = muốn, 能 = có khả năng khách quan, 会 = có kỹ năng đã học, 可以 = được phép.', 6);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 4, '能 - khả năng khách quan', 'wǒ zhōu mò néng dǎ gōng 。', '我周末能打工。', 'Cuối tuần tôi có thể đi làm thêm.', 'Cấu trúc "能 - khả năng khách quan" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "我周末能打工。" (Cuối tuần tôi có thể đi làm thêm.).', 7);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 4, '会 - kỹ năng đã học', 'wǒ huì shuō yì diǎn ér hàn yǔ 。', '我会说一点儿汉语。', 'Tôi biết nói một chút tiếng Hán.', 'Cấu trúc "会 - kỹ năng đã học" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "我会说一点儿汉语。" (Tôi biết nói một chút tiếng Hán.).', 8);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 5, 'Câu song tân ngữ', 'wǒ xiǎng sòng tā yí jiàn lǐ wù 。', '我想送他一件礼物。', 'Tôi muốn tặng anh ấy một món quà.', 'Cấu trúc "Câu song tân ngữ" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "我想送他一件礼物。" (Tôi muốn tặng anh ấy một món quà.).', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 5, 'Trợ động từ 要 (2)', 'nǐ yào sòng shén me lǐ wù ？', '你要送什么礼物？', 'Bạn muốn tặng quà gì?', 'Trợ động từ (要/能/会/可以...) luôn đứng TRƯỚC động từ chính để bổ sung nghĩa muốn/có thể/biết làm — khác nhau ở sắc thái: 想/要 = muốn, 能 = có khả năng khách quan, 会 = có kỹ năng đã học, 可以 = được phép.', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 5, 'Phó từ 还是 - hay là', 'sòng huā hái shì sòng dàn gāo ？', '送花还是送蛋糕？', 'Tặng hoa hay tặng bánh kem?', '"A还是B" là câu hỏi LỰA CHỌN giữa hai phương án, dịch là "A hay là B" — khác với "或者" chỉ dùng trong câu khẳng định (không phải câu hỏi).', 2);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 5, 'Phó từ 才 (1) - mới', 'tā xué le sān nián cái huì shuō hàn yǔ 。', '他学了三年才会说汉语。', 'Anh ấy học ba năm mới biết nói tiếng Hán.', 'Cấu trúc "Phó từ 才 (1) - mới" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "他学了三年才会说汉语。" (Anh ấy học ba năm mới biết nói tiếng Hán.).', 3);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 5, 'Câu chủ - vị làm vị ngữ', 'wǒ kǒu yǔ hé tīng lì dōu hěn hǎo 。', '我口语和听力都很好。', 'Nói và nghe của tôi đều tốt.', 'Cấu trúc "Câu chủ - vị làm vị ngữ" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "我口语和听力都很好。" (Nói và nghe của tôi đều tốt.).', 4);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 5, 'Tính từ làm trạng ngữ', 'tā nǔ lì xué xí hàn yǔ 。', '他努力学习汉语。', 'Anh ấy chăm chỉ học tiếng Hán.', 'Cấu trúc "Tính từ làm trạng ngữ" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "他努力学习汉语。" (Anh ấy chăm chỉ học tiếng Hán.).', 5);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 5, 'Bổ ngữ thời lượng', 'wǒ shàng le sì gè xiǎo shí de wǎng 。', '我上了四个小时的网。', 'Tôi lên mạng bốn tiếng.', 'Cấu trúc "Bổ ngữ thời lượng" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "我上了四个小时的网。" (Tôi lên mạng bốn tiếng.).', 6);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 5, 'Động từ trùng điệp', 'nǐ xiū xi xiū xi ba 。', '你休息休息吧。', 'Bạn nghỉ ngơi một chút đi.', 'Cấu trúc "Động từ trùng điệp" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "你休息休息吧。" (Bạn nghỉ ngơi một chút đi.).', 7);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 5, 'Câu hỏi với 是不是', 'nǐ shì bu shì wán yóu xì wán lèi le ？', '你是不是玩游戏玩累了？', 'Có phải bạn chơi game mệt rồi không?', '"是不是" có thể đặt ở đầu, giữa hoặc cuối câu để hỏi xác nhận lại một điều gì đó — giống "có phải... không" trong tiếng Việt.', 8);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 6, 'Phó từ 只好 - đành phải', 'nuǎn qì huài le ， wǒ men zhǐ hǎo chuān duō diǎn ér yī fu 。', '暖气坏了，我们只好穿多点儿衣服。', 'Lò sưởi hỏng rồi, chúng tôi đành phải mặc nhiều quần áo hơn.', '"只好" nghĩa là "đành phải", dùng khi không còn lựa chọn nào khác ngoài việc làm gì đó — mang sắc thái miễn cưỡng, bất đắc dĩ.', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 6, 'Bổ ngữ kết quả (1): V+好', 'nuǎn qì hái méi yǒu xiū hǎo 。', '暖气还没有修好。', 'Lò sưởi vẫn chưa sửa xong.', 'Cấu trúc "Bổ ngữ kết quả (1): V+好" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "暖气还没有修好。" (Lò sưởi vẫn chưa sửa xong.).', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 6, 'Lượng từ động lượng 遍', 'wǒ dǎ le sān biàn diàn huà 。', '我打了三遍电话。', 'Tôi đã gọi điện ba lần.', '"遍" là lượng từ chỉ SỐ LẦN thực hiện một hành động TRỌN VẸN từ đầu đến cuối — khác "次" chỉ đơn thuần đếm số lần.', 2);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 6, 'Bổ ngữ kết quả (2): V+到', 'kuài cān kě yǐ sòng dào jiā lǐ 。', '快餐可以送到家里。', 'Đồ ăn nhanh có thể giao đến tận nhà.', 'Cấu trúc "Bổ ngữ kết quả (2): V+到" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "快餐可以送到家里。" (Đồ ăn nhanh có thể giao đến tận nhà.).', 3);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 6, '又...又... - vừa...vừa...', 'zhè jiā kuài cān yòu pián yi yòu fāng biàn 。', '这家快餐又便宜又方便。', 'Đồ ăn nhanh ở đây vừa rẻ vừa tiện.', '"又" nghĩa là "lại" — diễn tả một hành động/sự việc LẶP LẠI đã từng xảy ra trước đó, thường dùng cho việc đã xảy ra rồi (không dùng cho tương lai, tương lai dùng "再").', 4);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 6, '对了 - à đúng rồi', 'duì le ， nǐ de dì zhǐ shì duō shǎo ？', '对了，你的地址是多少？', 'À đúng rồi, địa chỉ của bạn là gì?', 'Trợ từ "了" đặt ngay sau động từ để nhấn mạnh một hành động đã HOÀN THÀNH hoặc một sự việc/trạng thái vừa THAY ĐỔI. Đây là một trong những trợ từ quan trọng và hay gây nhầm lẫn nhất với người mới học.', 5);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 6, 'A跟(和)B不一样/一样', 'wǒ de shū gēn nǐ de bù yí yàng 。', '我的书跟你的不一样。', 'Sách của tôi khác sách của bạn.', '"A跟(和)B一样/不一样" dùng để so sánh sự GIỐNG/KHÁC NHAU giữa hai đối tượng, không phải so sánh hơn kém.', 6);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 6, 'Câu hỏi với 好吗', 'bǎ chuāng hù dǎ kāi ， hǎo ma ？', '把窗户打开，好吗？', 'Mở cửa sổ ra được không?', '"吗" là trợ từ đặt ở CUỐI câu để biến một câu khẳng định thành câu hỏi có/không — giống thêm dấu "?" và ý "có...không" trong tiếng Việt. Không cần đảo trật tự từ, chỉ cần thêm "吗" vào cuối.', 7);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 6, 'Câu chữ 把 (1)', 'wǒ bǎ dài zǐ fàng zài zhuō zi shàng le 。', '我把袋子放在桌子上了。', 'Tôi đã đặt cái túi lên bàn.', 'Câu chữ "把" dùng khi muốn nhấn mạnh TÁC ĐỘNG lên một sự vật cụ thể và kết quả của tác động đó, cấu trúc: Chủ ngữ + 把 + Tân ngữ (sự vật cụ thể) + Động từ + thành phần khác. Đây là một trong những cấu trúc khó nhất với người mới học vì tiếng Việt không có cấu trúc tương đương.', 8);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 7, 'Cụm từ với 的', 'zhè shì wǒ de zì xíng chē 。', '这是我的自行车。', 'Đây là xe đạp của tôi.', 'Cấu trúc "Cụm từ với 的" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "这是我的自行车。" (Đây là xe đạp của tôi.).', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 7, 'Phó từ 有点儿 - hơi', 'zhè liàng zì xíng chē yǒu diǎn er jiù 。', '这辆自行车有点儿旧。', 'Chiếc xe đạp này hơi cũ.', '"有点儿" đặt TRƯỚC tính từ, thường mang nghĩa KHÔNG HÀI LÒNG/hơi tiêu cực (hơi... quá) — khác "一点儿" đặt SAU tính từ mang nghĩa trung tính.', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 7, '算了 - thôi bỏ đi', 'suàn le ， wǒ men zǒu lù ba 。', '算了，我们走路吧。', 'Thôi bỏ đi, chúng ta đi bộ vậy.', 'Trợ từ "了" đặt ngay sau động từ để nhấn mạnh một hành động đã HOÀN THÀNH hoặc một sự việc/trạng thái vừa THAY ĐỔI. Đây là một trong những trợ từ quan trọng và hay gây nhầm lẫn nhất với người mới học.', 2);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 7, 'Phó từ 差不多 - gần như', 'jīn nián gēn qù nián chà bù duō lěng 。', '今年跟去年差不多冷。', 'Năm nay lạnh gần như năm ngoái.', '"差不多" nghĩa là "gần như, xấp xỉ", dùng để so sánh mức độ tương đương giữa hai thứ mà không cần chính xác tuyệt đối.', 3);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 7, 'Trợ từ 了 (3) - biến đổi', 'jīn nián dōng tiān biàn lěng le 。', '今年冬天变冷了。', 'Mùa đông năm nay lạnh hơn.', 'Trợ từ "了" đặt ngay sau động từ để nhấn mạnh một hành động đã HOÀN THÀNH hoặc một sự việc/trạng thái vừa THAY ĐỔI. Đây là một trong những trợ từ quan trọng và hay gây nhầm lẫn nhất với người mới học.', 4);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 7, '还可以 - cũng tạm được', 'jīn tiān tiān qì hái kě yǐ 。', '今天天气还可以。', 'Thời tiết hôm nay cũng tạm được.', '"还" mang nghĩa "vẫn còn/vẫn đang" khi đứng trước động từ/tính từ, diễn tả một trạng thái tiếp diễn chưa kết thúc.', 5);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 7, '为了 - vì, để', 'wèi le kàn wǒ ， mā ma jì lái le lǐ wù 。', '为了看我，妈妈寄来了礼物。', 'Để thăm tôi (dù xa), mẹ đã gửi quà đến.', 'Trợ từ "了" đặt ngay sau động từ để nhấn mạnh một hành động đã HOÀN THÀNH hoặc một sự việc/trạng thái vừa THAY ĐỔI. Đây là một trong những trợ từ quan trọng và hay gây nhầm lẫn nhất với người mới học.', 6);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 7, '如果 - nếu', 'rú guǒ nǐ xiǎng wǒ ， jiù dǎ diàn huà gěi wǒ 。', '如果你想我，就打电话给我。', 'Nếu bạn nhớ tôi, hãy gọi điện cho tôi.', '"如果/要是" nghĩa là "nếu", mở đầu câu điều kiện, thường đi cùng "就" ở vế sau: 如果...就... (nếu... thì...).', 7);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 7, 'Bổ ngữ xu hướng đơn giản', 'mā ma gěi wǒ jì lái le lǐ wù 。', '妈妈给我寄来了礼物。', 'Mẹ đã gửi quà đến cho tôi.', 'Cấu trúc "Bổ ngữ xu hướng đơn giản" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "妈妈给我寄来了礼物。" (Mẹ đã gửi quà đến cho tôi.).', 8);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 8, '听不懂 - nghe không hiểu', 'wǒ tīng bù dǒng tā men shuō de huà 。', '我听不懂他们说的话。', 'Tôi không hiểu họ nói gì.', 'Cấu trúc "động từ + 不 + kết quả/bổ ngữ" diễn tả KHÔNG THỂ đạt được kết quả đó, ví dụ: 听不懂 (nghe không hiểu) — khác với "不听" (không nghe, mang tính chủ động không muốn nghe).', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 8, '虽然...但是/可是/还是...', 'suī rán tā shuō dé hěn kuài ， dàn shì wǒ tīng dǒng le 。', '虽然他说得很快，但是我听懂了。', 'Mặc dù anh ấy nói rất nhanh, nhưng tôi đã hiểu.', '"A还是B" là câu hỏi LỰA CHỌN giữa hai phương án, dịch là "A hay là B" — khác với "或者" chỉ dùng trong câu khẳng định (không phải câu hỏi).', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 8, 'Phó từ 好好儿', 'qǐng nǐ hǎo hāo er shuō yí biàn 。', '请你好好儿说一遍。', 'Xin bạn nói lại một cách rõ ràng.', '"好好儿" nghĩa là "một cách cẩn thận, kỹ càng, đàng hoàng", thường đặt trước động từ để nhấn mạnh cách làm việc nghiêm túc.', 2);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 8, '快要...了/要...了/快...了/就要...了', 'shèng dàn jié kuài dào le 。', '圣诞节快到了。', 'Giáng sinh sắp đến rồi.', 'Trợ từ "了" đặt ngay sau động từ để nhấn mạnh một hành động đã HOÀN THÀNH hoặc một sự việc/trạng thái vừa THAY ĐỔI. Đây là một trong những trợ từ quan trọng và hay gây nhầm lẫn nhất với người mới học.', 3);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 8, '特别是 - đặc biệt là', 'dà jiā dōu xǐ huan guò jié ， tè bié shì hái zi 。', '大家都喜欢过节，特别是孩子。', 'Ai cũng thích lễ hội, đặc biệt là trẻ em.', '"特别是" nghĩa là "đặc biệt là", dùng để nhấn mạnh một trường hợp/đối tượng cụ thể trong một nhóm chung đã nhắc đến trước đó.', 4);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 8, '要是 - nếu như', 'yào shi yǒu shí jiān ， wǒ men jiù qù jù huì 。', '要是有时间，我们就去聚会。', 'Nếu có thời gian, chúng ta sẽ đi tụ họp.', '"如果/要是" nghĩa là "nếu", mở đầu câu điều kiện, thường đi cùng "就" ở vế sau: 如果...就... (nếu... thì...).', 5);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 8, '一边...一边... - vừa...vừa...', 'tā yì biān chī fàn yì biān kàn diàn shì 。', '他一边吃饭一边看电视。', 'Anh ấy vừa ăn cơm vừa xem tivi.', '"一边...一边..." nghĩa là "vừa... vừa...", diễn tả hai hành động xảy ra ĐỒNG THỜI, cả hai vế đều phải là động từ.', 6);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 8, '正在.../在.../正...+呢 - đang...', 'wǒ zhèng zài kàn diàn shì ne 。', '我正在看电视呢。', 'Tôi đang xem tivi.', '"呢" ở cuối câu dùng để hỏi lại, hỏi tiếp về cùng một chủ đề (giống "còn...thì sao?" trong tiếng Việt), hoặc để hỏi "...đâu rồi?" khi hỏi vị trí. Rất hay dùng sau khi vừa trả lời xong một câu hỏi để hỏi lại người kia.', 7);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 8, 'Đại từ/danh từ+那儿/这儿 chỉ nơi chốn', 'tā zài nà ér kàn xīn wén 。', '他在那儿看新闻。', 'Anh ấy đang xem tin tức ở đó.', '"这儿/那儿" (ở đây/ở đó) thường đi sau đại từ nhân xưng hoặc danh từ chỉ người để tạo thành cụm chỉ ĐỊA ĐIỂM — ví dụ: 我这儿 (chỗ tôi, ở chỗ tôi).', 8);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 9, 'Số phỏng chừng (3)', 'cháng chéng yǒu bā qiān bā bǎi wǔ shí duō gōng lǐ 。', '长城有八千八百五十多公里。', 'Vạn Lý Trường Thành dài hơn 8850km.', 'Cấu trúc "Số phỏng chừng (3)" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "长城有八千八百五十多公里。" (Vạn Lý Trường Thành dài hơn 8850km.).', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 9, 'Giới từ 通过 - thông qua', 'tōng guò zhè běn shū ， wǒ liǎo jiě le cháng chéng de lì shǐ 。', '通过这本书，我了解了长城的历史。', 'Thông qua cuốn sách này, tôi hiểu được lịch sử Trường Thành.', '"通过" (giới từ) nghĩa là "thông qua, bằng cách", dùng để nêu PHƯƠNG TIỆN/CÁCH THỨC đạt được điều gì đó, đặt ở đầu câu.', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 9, 'Phó từ 原来 - hóa ra', 'yuán lái cháng chéng shì gǔ dài jiàn de 。', '原来长城是古代建的。', 'Hóa ra Trường Thành được xây từ thời cổ đại.', '"原来" có hai nghĩa: (1) "hóa ra" — khi vừa phát hiện ra sự thật bất ngờ; (2) "vốn dĩ, ban đầu" — chỉ trạng thái trước khi có thay đổi.', 2);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 9, 'Bổ ngữ trạng thái (tình thái bổ ngữ)', 'wǎn huì kāi dé fēi cháng chéng gōng 。', '晚会开得非常成功。', 'Buổi tiệc rất thành công.', 'Bổ ngữ trạng thái (động từ + 得 + tính từ/cụm từ) mô tả MỨC ĐỘ hoặc TRẠNG THÁI của hành động, ví dụ: 开得很成功 (tổ chức rất thành công) — "得" là dấu hiệu nhận biết.', 3);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 9, 'Động từ 爱 - yêu, thích', 'tā ài chàng gē ， yě ài tiào wǔ 。', '他爱唱歌，也爱跳舞。', 'Anh ấy thích hát, cũng thích nhảy múa.', 'Cấu trúc "Động từ 爱 - yêu, thích" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "他爱唱歌，也爱跳舞。" (Anh ấy thích hát, cũng thích nhảy múa.).', 4);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 9, 'Phó từ 可能 - có thể', 'míng tiān kě néng huì xià yǔ 。', '明天可能会下雨。', 'Ngày mai có lẽ sẽ mưa.', '"可能" (phó từ) nghĩa là "có thể, có lẽ", đặt trước động từ để diễn tả khả năng/dự đoán, không chắc chắn 100%.', 5);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 9, 'Adj/V+极了 - cực kỳ...', 'nà duàn jīng lì yǒu yì sī jí le 。', '那段经历有意思极了。', 'Trải nghiệm đó cực kỳ thú vị.', 'Trợ từ "了" đặt ngay sau động từ để nhấn mạnh một hành động đã HOÀN THÀNH hoặc một sự việc/trạng thái vừa THAY ĐỔI. Đây là một trong những trợ từ quan trọng và hay gây nhầm lẫn nhất với người mới học.', 6);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 9, 'V+过 - đã từng', 'wǒ dāng guò yīng yǔ lǎo shī 。', '我当过英语老师。', 'Tôi từng là giáo viên tiếng Anh.', 'Trợ từ "过" đặt sau động từ để nói về KINH NGHIỆM đã từng trải qua trong quá khứ (dù bây giờ không còn nữa) — khác "了" chỉ đơn thuần nói việc đã hoàn thành.', 7);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 9, '当...的时候 - khi...', 'dāng wǒ dāng lǎo shī de shí hòu ， xué dào le hěn duō 。', '当我当老师的时候，学到了很多。', 'Khi tôi làm giáo viên, tôi đã học được nhiều điều.', '"当...的时候" nghĩa là "khi... (thì)", dùng để chỉ thời điểm một sự việc khác đang xảy ra.', 8);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 10, 'V+着 - duy trì hành động/trạng thái', 'tā xiào zhe gēn wǒ dǎ zhāo hū 。', '他笑着跟我打招呼。', 'Anh ấy cười và chào tôi.', 'Trợ từ "着" đặt sau động từ để diễn tả một hành động/trạng thái đang được DUY TRÌ liên tục, thường dùng khi mô tả một trạng thái nền cho hành động khác.', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 10, '不是A，而是B', 'tā bú shì chí dào ， ér shì wàng le shí jiān 。', '他不是迟到，而是忘了时间。', 'Anh ấy không phải đến muộn, mà là quên giờ.', '"不是A，而是B" nghĩa là "không phải A, mà là B", dùng để đính chính lại một thông tin sai.', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 10, '不/没...不/没... (song phủ định)', 'bù nǔ lì jiù bú huì jìn bù 。', '不努力就不会进步。', 'Không cố gắng thì sẽ không tiến bộ.', 'Cấu trúc song phủ định (không...không...) mang nghĩa KHẲNG ĐỊNH mạnh mẽ hơn — ví dụ: 不努力就不会进步 (không cố gắng thì sẽ không tiến bộ) = phải cố gắng mới tiến bộ được.', 2);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 10, '从来 - từ trước đến nay', 'tā cóng lái méi xiǎng guò yào huí jiā 。', '他从来没想过要回家。', 'Anh ấy từ trước đến nay chưa từng nghĩ sẽ về nhà.', '"从来" nghĩa là "từ trước đến nay", thường đi với "没" để nhấn mạnh việc CHƯA TỪNG xảy ra.', 3);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 10, '不A不B', 'tā bù kū bú nào ， hěn dǒng shì 。', '他不哭不闹，很懂事。', 'Nó không khóc không quấy, rất ngoan.', '"不A不B" là cách nói phủ định kép với hai từ trái nghĩa/liên quan, thường mang nghĩa "không A cũng không B" hoặc diễn tả trạng thái trung tính, ngoan ngoãn.', 4);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 10, 'Nơi chốn+V+着+N (câu tồn tại)', 'jī chǎng zhàn zhe hěn duō jiē jī de rén 。', '机场站着很多接机的人。', 'Ở sân bay đứng rất nhiều người đón khách.', 'Trợ từ "着" đặt sau động từ để diễn tả một hành động/trạng thái đang được DUY TRÌ liên tục, thường dùng khi mô tả một trạng thái nền cho hành động khác.', 5);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 10, 'Bổ ngữ xu hướng phức hợp', 'tā bǎ là jiāo bān jìn lái le 。', '她把辣椒搬进来了。', 'Cô ấy đã mang ớt vào.', 'Cấu trúc "Bổ ngữ xu hướng phức hợp" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "她把辣椒搬进来了。" (Cô ấy đã mang ớt vào.).', 6);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 10, '既...也/又... - vừa...vừa...', 'tā jì cōng ming yòu qín láo 。', '她既聪明又勤劳。', 'Cô ấy vừa thông minh vừa chăm chỉ.', '"又" nghĩa là "lại" — diễn tả một hành động/sự việc LẶP LẠI đã từng xảy ra trước đó, thường dùng cho việc đã xảy ra rồi (không dùng cho tương lai, tương lai dùng "再").', 7);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 10, '把+O+V+bổ ngữ xu hướng', 'tā bǎ là jiāo ná chū lái le 。', '她把辣椒拿出来了。', 'Cô ấy đã lấy ớt ra.', 'Cấu trúc "把+O+V+bổ ngữ xu hướng" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "她把辣椒拿出来了。" (Cô ấy đã lấy ớt ra.).', 8);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 11, 'Câu 是...的 (1)', 'wǒ shì qù nián lái zhōng guó de 。', '我是去年来中国的。', 'Tôi đến Trung Quốc từ năm ngoái.', 'Câu "是...的" dùng để NHẤN MẠNH một chi tiết (thời gian, địa điểm, cách thức) của một sự việc ĐÃ XẢY RA, mà người nói và người nghe đều đã biết sự việc đó — không phải để giới thiệu thông tin mới.', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 11, '不但...而且... - không những...mà còn...', 'tā bú dàn xǐ huan zhōng guó wén huà ， ér qiě huì shuō hàn yǔ 。', '他不但喜欢中国文化，而且会说汉语。', 'Anh ấy không những thích văn hóa Trung Quốc, mà còn biết nói tiếng Hán.', '"不但...而且..." nghĩa là "không những... mà còn...", dùng để bổ sung một ý tăng tiến so với vế đầu.', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 11, '其实 - thực ra', 'qí shí wǒ yì zhí xiǎng lái zhōng guó liú xué 。', '其实我一直想来中国留学。', 'Thực ra tôi luôn muốn đến Trung Quốc du học.', '"其实" nghĩa là "thực ra", dùng để đưa ra một sự thật khác/bổ sung so với điều người nghe có thể nghĩ trước đó.', 2);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 11, 'V1+着+V2 - vừa...vừa...', 'tā zhàn zhe chī zǎo fàn 。', '他站着吃早饭。', 'Anh ấy đứng ăn sáng.', 'Cấu trúc "V1+着+V2 - vừa...vừa..." — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "他站着吃早饭。" (Anh ấy đứng ăn sáng.).', 3);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 11, 'Từ nghi vấn+也/都... (bất kể)', 'nǎ ér dōu méi yǒu zuò wèi 。', '哪儿都没有座位。', 'Chỗ nào cũng không có chỗ ngồi.', 'Cấu trúc "Từ nghi vấn+也/都... (bất kể)" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "哪儿都没有座位。" (Chỗ nào cũng không có chỗ ngồi.).', 4);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 11, '越A越B - càng...càng...', 'wǒ yuè lái yuè shì yìng zhè lǐ de shēng huó le 。', '我越来越适应这里的生活了。', 'Tôi càng ngày càng thích nghi với cuộc sống ở đây.', '"越A越B" nghĩa là "càng A càng B", diễn tả mức độ B tăng theo cùng chiều với mức độ A.', 5);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 11, 'V+得/不+kết quả/xu hướng (khả năng bổ ngữ 1)', 'wǒ yí gè rén zhào gù dé le zì jǐ 。', '我一个人照顾得了自己。', 'Tôi có thể tự chăm sóc bản thân một mình.', 'Cấu trúc "V+得/不+kết quả/xu hướng (khả năng bổ ngữ 1)" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "我一个人照顾得了自己。" (Tôi có thể tự chăm sóc bản thân một mình.).', 6);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 12, 'V/Adj+起来 - bắt đầu...', 'tā yì tí dào āi jí jiù xīng fèn qǐ lái 。', '他一提到埃及就兴奋起来。', 'Anh ấy vừa nhắc đến Ai Cập liền phấn khích hẳn lên.', '"V/Adj + 起来" diễn tả một hành động/trạng thái BẮT ĐẦU xảy ra và tiếp diễn, hoặc dùng để ĐÁNH GIÁ nhận xét về một sự việc (nhìn/nghe/làm... có vẻ như thế nào).', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 12, 'V/Adj+下去 - tiếp tục...', 'zhè ge jì huà wǒ men yào jiān chí xià qù 。', '这个计划我们要坚持下去。', 'Kế hoạch này chúng ta phải kiên trì tiếp tục.', '"V/Adj + 下去" diễn tả một hành động TIẾP TỤC diễn ra (thường đã bắt đầu từ trước), mang nghĩa "tiếp tục... đi".', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 12, 'V+什么 - ngăn cản, khuyên bảo', 'nǐ qù āi jí gàn shén me ？', '你去埃及干什么？', 'Bạn đi Ai Cập làm gì?', '"động từ + 什么" trong câu cảm thán/khuyên bảo mang nghĩa NGĂN CẢN, phản đối việc gì đó — không phải hỏi "làm gì" theo nghĩa đen.', 2);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 12, 'A比B+Adj/VP - so sánh hơn', 'xiàn zài de gù xiāng bǐ cóng qián piào liang duō le 。', '现在的故乡比从前漂亮多了。', 'Quê hương bây giờ đẹp hơn trước nhiều.', 'Câu so sánh "A比B + tính từ" nghĩa là "A hơn B ở điểm gì đó", có thể thêm mức độ cụ thể phía sau hoặc dùng 还/更 để nhấn mạnh "còn... hơn".', 3);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 12, 'A比B+Adj/VP+mức độ', 'zhè lǐ bǐ wǒ jì yì zhōng dà dé duō 。', '这里比我记忆中大得多。', 'Nơi đây to hơn nhiều so với trong ký ức của tôi.', 'Câu so sánh "A比B + tính từ" nghĩa là "A hơn B ở điểm gì đó", có thể thêm mức độ cụ thể phía sau hoặc dùng 还/更 để nhấn mạnh "còn... hơn".', 4);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 12, 'A比B+还/更+Adj/VP', 'biàn huà bǐ wǒ xiǎng xiàng de hái dà 。', '变化比我想象的还大。', 'Sự thay đổi còn lớn hơn tôi tưởng tượng.', '"还" mang nghĩa "vẫn còn/vẫn đang" khi đứng trước động từ/tính từ, diễn tả một trạng thái tiếp diễn chưa kết thúc.', 5);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 12, 'N1让/叫N2+V', 'lǎo shī ràng wǒ men duō dú shū 。', '老师让我们多读书。', 'Thầy cô để chúng tôi đọc sách nhiều hơn.', '"N1 让/叫 N2 + động từ" nghĩa là "N1 khiến/bảo N2 làm gì", N1 là người ra lệnh/yêu cầu, N2 là người thực hiện hành động.', 6);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 12, 'A不如B - A không bằng B', 'yán gé bù rú lǐ jiě zhòng yào 。', '严格不如理解重要。', 'Nghiêm khắc không quan trọng bằng thấu hiểu.', '"A不如B" nghĩa là "A không bằng B", một cách so sánh khác ngoài "比", thường dùng khi phủ định sự hơn kém.', 7);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 12, 'A有(没有)B(这么/那么)+Adj/VP', 'tā méi yǒu tā gē ge nà me nài xīn 。', '他没有他哥哥那么耐心。', 'Cậu ấy không kiên nhẫn bằng anh trai mình.', 'Cấu trúc "A有(没有)B(这么/那么)+Adj/VP" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "他没有他哥哥那么耐心。" (Cậu ấy không kiên nhẫn bằng anh trai mình.).', 8);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 13, '一+lượng từ(N)一+lượng từ(N) (trùng điệp)', 'tā yì tiān yi tiān dì kāi xīn qǐ lái 。', '他一天一天地开心起来。', 'Anh ấy vui vẻ dần lên từng ngày.', 'Tiếng Trung luôn cần một "lượng từ" đứng giữa số đếm và danh từ (khác tiếng Việt không bắt buộc) — ví dụ "一个人" (một người), "两本书" (hai quyển sách). "个" là lượng từ chung, dùng được cho rất nhiều danh từ khi không chắc dùng lượng từ nào.', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 13, 'Bổ ngữ động lượng', 'xiào yi xiào ， xīn qíng jiù hǎo le 。', '笑一笑，心情就好了。', 'Cười một cái, tâm trạng liền tốt hơn.', 'Cấu trúc "Bổ ngữ động lượng" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "笑一笑，心情就好了。" (Cười một cái, tâm trạng liền tốt hơn.).', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 13, '一lượng từ比一lượng từ+Adj/VP', 'tā yì tiān bǐ yì tiān kuài lè 。', '他一天比一天快乐。', 'Anh ấy ngày càng vui vẻ hơn.', 'Tiếng Trung luôn cần một "lượng từ" đứng giữa số đếm và danh từ (khác tiếng Việt không bắt buộc) — ví dụ "一个人" (một người), "两本书" (hai quyển sách). "个" là lượng từ chung, dùng được cho rất nhiều danh từ khi không chắc dùng lượng từ nào.', 2);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 13, 'Từ nghi vấn phiếm chỉ (không xác định)', 'shū lǐ hǎo xiàng cáng zhe shén me dōng xī 。', '书里好像藏着什么东西。', 'Trong sách hình như giấu thứ gì đó.', 'Cấu trúc "Từ nghi vấn phiếm chỉ (không xác định)" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "书里好像藏着什么东西。" (Trong sách hình như giấu thứ gì đó.).', 3);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 13, 'Từ nghi vấn phiếm chỉ (bất kỳ)', 'shuí dōu méi fā xiàn zhè zhī xiǎo mǎ yǐ 。', '谁都没发现这只小蚂蚁。', 'Không ai phát hiện con kiến nhỏ này.', 'Cấu trúc "Từ nghi vấn phiếm chỉ (bất kỳ)" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "谁都没发现这只小蚂蚁。" (Không ai phát hiện con kiến nhỏ này.).', 4);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 13, 'V+出来 - bổ ngữ xu hướng mở rộng', 'tā bǎ mǎ yǐ de mì mì kàn chū lái le 。', '他把蚂蚁的秘密看出来了。', 'Cậu ấy đã nhìn ra bí mật của con kiến.', '"V + 出来" (nghĩa mở rộng) không chỉ mang nghĩa "đi/lấy ra" theo hướng vật lý mà còn diễn tả việc NHẬN RA, PHÁT HIỆN RA điều gì đó.', 5);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 13, '对...来说 - đối với...mà nói', 'duì wài guó rén lái shuō ， shēng diào hěn nán 。', '对外国人来说，声调很难。', 'Đối với người nước ngoài mà nói, thanh điệu rất khó.', '"对...(来说)" nghĩa là "đối với... (mà nói)", dùng để nêu quan điểm/cảm nhận của một ai đó hoặc mức độ ảnh hưởng của việc gì với ai/cái gì đó.', 6);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 13, '把+A+V成+B - biến A thành B', 'tā bǎ zhěn tou shuō chéng le zhēn tóu 。', '他把枕头说成了针头。', 'Anh ấy đã nói nhầm ''gối'' thành ''đầu kim''.', '"把 + A + V + 成 + B" nghĩa là "biến/nói/làm A thành B", nhấn mạnh sự thay đổi kết quả từ trạng thái A sang B.', 7);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 13, 'Câu phản vấn (1)', 'zhè zěn me huì shì zhēn tóu ne ？', '这怎么会是针头呢？', 'Cái này sao lại là đầu kim được chứ?', 'Cấu trúc "Câu phản vấn (1)" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "这怎么会是针头呢？" (Cái này sao lại là đầu kim được chứ?).', 8);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 14, '除了...(以外)，... - ngoài...ra', 'chú le xué xí ， tā hái xǐ huan yùn dòng 。', '除了学习，他还喜欢运动。', 'Ngoài học tập ra, anh ấy còn thích thể thao.', 'Trợ từ "了" đặt ngay sau động từ để nhấn mạnh một hành động đã HOÀN THÀNH hoặc một sự việc/trạng thái vừa THAY ĐỔI. Đây là một trong những trợ từ quan trọng và hay gây nhầm lẫn nhất với người mới học.', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 14, '不是A就是B - không A thì B', 'tā bú shì kàn shū jiù shì xiě xìn 。', '他不是看书就是写信。', 'Anh ấy không đọc sách thì viết thư.', '"不是A就是B" nghĩa là "không A thì B", diễn tả hai khả năng loại trừ lẫn nhau, chắc chắn phải là một trong hai.', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 14, 'Danh từ/lượng từ trùng điệp', 'fēng fēng xìn dōu xiě dé hěn rèn zhēn 。', '封封信都写得很认真。', 'Từng lá thư đều được viết rất chăm chút.', 'Tiếng Trung luôn cần một "lượng từ" đứng giữa số đếm và danh từ (khác tiếng Việt không bắt buộc) — ví dụ "一个人" (một người), "两本书" (hai quyển sách). "个" là lượng từ chung, dùng được cho rất nhiều danh từ khi không chắc dùng lượng từ nào.', 2);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 14, 'Cách đọc số trăm, nghìn, vạn', 'chē fèi yí gòng sān shí liù kuài 。', '车费一共三十六块。', 'Tiền xe tổng cộng ba mươi sáu đồng.', 'Cấu trúc "Cách đọc số trăm, nghìn, vạn" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "车费一共三十六块。" (Tiền xe tổng cộng ba mươi sáu đồng.).', 3);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 14, 'Câu chữ 被 - bị động', 'wǒ chà diǎn ér bèi sī jī piàn le 。', '我差点儿被司机骗了。', 'Tôi suýt bị tài xế lừa.', 'Câu chữ "被" là câu BỊ ĐỘNG, cấu trúc: Đối tượng bị tác động + 被 + (chủ thể) + Động từ + kết quả. Dùng khi muốn nhấn mạnh KẾT QUẢ xảy ra với đối tượng, thường mang sắc thái không mong muốn.', 4);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 14, '幸好 - may mà', 'xìng hǎo sī jī hěn lǎo shí 。', '幸好司机很老实。', 'May mà tài xế rất thật thà.', '"幸好" nghĩa là "may mà, may thay", đặt đầu câu để diễn tả một điều may mắn đã ngăn một hậu quả xấu hơn xảy ra.', 5);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 14, 'A是A,但(是)/可(是)/就是...', 'lù shì yuǎn ， dàn shì xìn gē hái shì fēi huí lái le 。', '路是远，但是信鸽还是飞回来了。', 'Đường thì xa, nhưng bồ câu vẫn bay về được.', 'Cấu trúc "A是A,但(是)/可(是)/就是..." — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "路是远，但是信鸽还是飞回来了。" (Đường thì xa, nhưng bồ câu vẫn bay về được.).', 6);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 14, 'Câu bị động không dấu hiệu', 'xìn gē xùn liàn hǎo le 。', '信鸽训练好了。', 'Bồ câu đã được huấn luyện xong.', 'Cấu trúc "Câu bị động không dấu hiệu" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "信鸽训练好了。" (Bồ câu đã được huấn luyện xong.).', 7);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 14, '当...的时候 - khi...', 'dāng xìn gē fēi huí lái de shí hòu ， dà jiā dōu hěn jīng yà 。', '当信鸽飞回来的时候，大家都很惊讶。', 'Khi bồ câu bay về, mọi người đều ngạc nhiên.', '"当...的时候" nghĩa là "khi... (thì)", dùng để chỉ thời điểm một sự việc khác đang xảy ra.', 8);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 15, '把+O+V/VP+số lượng thời gian', 'tā bǎ biǎo bō kuài sān fēn zhōng 。', '他把表拨快三分钟。', 'Anh ấy vặn đồng hồ nhanh lên ba phút.', 'Cấu trúc "把+O+V/VP+số lượng thời gian" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "他把表拨快三分钟。" (Anh ấy vặn đồng hồ nhanh lên ba phút.).', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 15, 'Câu phản vấn (2)', 'nán dào nǐ bù zhī dào huì chí dào ma ？', '难道你不知道会迟到吗？', 'Chẳng lẽ bạn không biết sẽ đến muộn sao?', 'Cấu trúc "Câu phản vấn (2)" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "难道你不知道会迟到吗？" (Chẳng lẽ bạn không biết sẽ đến muộn sao?).', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 15, '难道 - chẳng lẽ', 'nán dào zhè yàng jiù néng zhǔn shí le ma ？', '难道这样就能准时了吗？', 'Chẳng lẽ làm vậy là có thể đúng giờ được sao?', '"难道" mở đầu câu phản vấn, dịch là "chẳng lẽ...", thể hiện sự nghi ngờ hoặc không tin vào điều gì đó.', 2);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 15, '尽管...,但(是)/可(是)/却...', 'jǐn guǎn chí dào le ， tā què hái shì hěn kāi xīn 。', '尽管迟到了，他却还是很开心。', 'Mặc dù đến muộn, anh ấy vẫn rất vui.', '"尽管...但(是)/可(是)/却..." nghĩa là "mặc dù... nhưng...", gần giống "虽然...但是..." nhưng nhấn mạnh sự nhượng bộ rõ hơn.', 3);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 15, '到底 - rốt cuộc', 'tā dào dǐ lái bu lái ？', '他到底来不来？', 'Rốt cuộc anh ấy có đến hay không?', '"到底" nghĩa là "rốt cuộc", dùng trong câu hỏi để thúc giục có câu trả lời dứt khoát, hoặc "đến cùng" khi đi sau động từ.', 4);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 15, '即使...,也/还... - dù cho...cũng...', 'jí shǐ kàn bú jiàn ， tā yě néng tīng dǒng diàn yǐng de qíng jié 。', '即使看不见，他也能听懂电影的情节。', 'Dù không nhìn thấy, anh ấy vẫn nghe hiểu được tình tiết phim.', '"还" mang nghĩa "vẫn còn/vẫn đang" khi đứng trước động từ/tính từ, diễn tả một trạng thái tiếp diễn chưa kết thúc.', 5);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 15, '(好)像...似的 - giống như...', 'tā tīng dé hǎo xiàng kàn jiàn le shì de 。', '他听得好像看见了似的。', 'Anh ấy nghe mà giống như nhìn thấy vậy.', '"(好)像...似的" nghĩa là "giống như...", dùng để so sánh, ví von một sự việc với một hình ảnh khác.', 6);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 15, '来 biểu thị số phỏng chừng', 'diàn yǐng yuàn lǐ zuò le sān shí lái gè rén 。', '电影院里坐了三十来个人。', 'Trong rạp có khoảng ba mươi người.', 'Cấu trúc "来 biểu thị số phỏng chừng" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "电影院里坐了三十来个人。" (Trong rạp có khoảng ba mươi người.).', 7);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 16, '只有...才... - chỉ có...mới...', 'zhǐ yǒu jiān chí xiě xìn ， cái néng bǎo chí yǒu yì 。', '只有坚持写信，才能保持友谊。', 'Chỉ có kiên trì viết thư mới giữ được tình bạn.', '"只有...才..." nghĩa là "chỉ có... mới...", nêu điều kiện DUY NHẤT để đạt được kết quả ở vế sau — điều kiện chặt hơn "如果...就...".', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 16, 'Câu 是...的 (2)', 'wǒ men shì tōng guò xiě xìn rèn shi de 。', '我们是通过写信认识的。', 'Chúng tôi quen nhau qua việc viết thư.', 'Câu "是...的" dùng để NHẤN MẠNH một chi tiết (thời gian, địa điểm, cách thức) của một sự việc ĐÃ XẢY RA, mà người nói và người nghe đều đã biết sự việc đó — không phải để giới thiệu thông tin mới.', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 16, '好在 - may mà', 'hǎo zài yǒu fān yì ruǎn jiàn bāng máng 。', '好在有翻译软件帮忙。', 'May mà có phần mềm dịch giúp đỡ.', '"好在" nghĩa là "may mà, may thay" (giống "幸好"), đặt đầu câu để nói về yếu tố may mắn giúp tránh điều không hay.', 2);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 16, '把+O+V(一/了)V/V一下', 'tā bǎ qián ná le ná ， hái shì mò shōu xià 。', '他把钱拿了拿，还是没收下。', 'Anh ấy cầm tiền lên xem, rồi vẫn không nhận.', '"一下" đặt sau động từ để làm hành động nghe NHẸ NHÀNG, ngắn gọn hơn — như "thử xem", "một chút", "một lát". Ví dụ: 看一下 (xem thử một chút), 休息一下 (nghỉ một lát).', 3);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 16, '从...起 - kể từ...', 'cóng jīn tiān qǐ ， wǒ yào gèng zì xìn 。', '从今天起，我要更自信。', 'Kể từ hôm nay, tôi sẽ tự tin hơn.', '"从...起" nghĩa là "kể từ...", đánh dấu điểm bắt đầu của một khoảng thời gian hoặc hành động.', 4);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 16, '千万 - nhất định', 'qiān wàn bú yào fàng qì zì jǐ de zūn yán 。', '千万不要放弃自己的尊严。', 'Nhất định đừng từ bỏ nhân phẩm của mình.', '"千万" nghĩa là "nhất định (đừng/phải)", dùng để nhấn mạnh một lời dặn dò, cảnh báo quan trọng, thường đi cùng "不要/别".', 5);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 16, '不管...都/也... - bất kể...đều...', 'bù guǎn duō nán ， yú gōng dōu yào bǎ shān yí zǒu 。', '不管多难，愚公都要把山移走。', 'Bất kể khó khăn thế nào, Ngu Công đều muốn dời núi đi.', '"不管...都/也..." nghĩa là "bất kể... đều...", dùng khi kết quả ở vế sau không thay đổi dù điều kiện ở vế trước là gì.', 6);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 16, '..., 再说... - huống chi', 'shān zhè me dà ， zài shuō wǒ men rén zhè me shǎo ， zěn me yí ？', '山这么大，再说我们人这么少，怎么移？', 'Núi to như vậy, huống chi người chúng ta lại ít, làm sao dời được?', '"再说" nghĩa là "huống chi, hơn nữa", dùng để bổ sung thêm một lý do nữa cho lập luận đã nêu.', 7);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 16, 'V+到底 - làm đến cùng', 'yú gōng jué xīn bǎ yí shān zuò dào dǐ 。', '愚公决心把移山做到底。', 'Ngu Công quyết tâm dời núi đến cùng.', '"到底" nghĩa là "rốt cuộc", dùng trong câu hỏi để thúc giục có câu trả lời dứt khoát, hoặc "đến cùng" khi đi sau động từ.', 8);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 17, '不必 - không cần', 'xiàn zài bú bì dài xiàn jīn le 。', '现在不必带现金了。', 'Bây giờ không cần mang tiền mặt nữa.', '"不必" nghĩa là "không cần", nhẹ nhàng hơn "不用", dùng để nói một việc không bắt buộc phải làm.', 0);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 17, '只要...就... - chỉ cần...thì...', 'zhǐ yào yǒu yì zhāng kǎ ， jiù néng zuò chē 、 mǎi dōng xī 。', '只要有一张卡，就能坐车、买东西。', 'Chỉ cần có một tấm thẻ là có thể đi xe, mua đồ.', '"只要...就..." nghĩa là "chỉ cần... thì...", nêu điều kiện ĐỦ (không cần điều kiện nào khác) để có kết quả ở vế sau — khác "只有...才..." là điều kiện DUY NHẤT.', 1);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 17, '既然...就... - đã như vậy thì...', 'jì rán kǎ zhè me fāng biàn ， wǒ men jiù yòng kǎ ba 。', '既然卡这么方便，我们就用卡吧。', 'Đã tiện như vậy thì chúng ta dùng thẻ thôi.', '"既然...就..." nghĩa là "đã (như vậy) thì...", dùng khi một sự thật đã được xác nhận và đưa ra kết luận/quyết định dựa trên sự thật đó.', 2);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 17, 'V+起来+đánh giá', 'dī tàn shēng huó zuò qǐ lái bìng bù nán 。', '低碳生活做起来并不难。', 'Sống ít carbon làm ra thì không khó.', 'Cấu trúc "V+起来+đánh giá" — hãy quan sát kỹ câu ví dụ bên dưới để hiểu cách dùng trong ngữ cảnh thực tế: "低碳生活做起来并不难。" (Sống ít carbon làm ra thì không khó.).', 3);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 17, '怎么也/都+V+不+kết quả', 'zěn me yě gǎi bù liǎo làng fèi de xí guàn 。', '怎么也改不了浪费的习惯。', 'Thế nào cũng không sửa được thói quen lãng phí.', '"怎么" dùng để hỏi CÁCH THỨC (làm thế nào) hoặc hỏi LÝ DO (tại sao, thể hiện sự ngạc nhiên) tùy vào ngữ cảnh.', 4);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 17, '连...都/也... - thậm chí...cũng...', 'lián yì zhāng zhǐ wǒ yě shè bù dé làng fèi 。', '连一张纸我也舍不得浪费。', 'Thậm chí một tờ giấy tôi cũng không nỡ lãng phí.', '"连...都/也..." nghĩa là "thậm chí... cũng...", dùng để nhấn mạnh một trường hợp CỰC ĐOAN nhất trong so sánh, làm nổi bật ý toàn bộ câu.', 5);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 17, '哪怕...也... - dù cho...cũng...', 'nǎ pà zài lèi ， tā yě yào péi ér zi pá wán cháng chéng 。', '哪怕再累，他也要陪儿子爬完长城。', 'Dù có mệt đến mấy, ông cũng muốn đồng hành cùng con trai leo hết Trường Thành.', '"哪怕...也..." nghĩa là "dù cho... cũng...", tương tự "即使...也..." nhưng thường nhấn mạnh mức độ khó khăn/cực đoan hơn.', 6);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 17, '万一 - lỡ như', 'wàn yī tǐ lì bú gòu ， wǒ men jiù xiū xi yí xià 。', '万一体力不够，我们就休息一下。', 'Lỡ như thể lực không đủ, chúng ta nghỉ một chút.', '"万一" nghĩa là "lỡ như, nhỡ đâu", dùng để nêu một tình huống XẤU có thể (dù ít khả năng) xảy ra, cần đề phòng trước.', 7);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 17, '用不着 - không cần đến', 'zhè me jìn ， yòng bù zhe zuò chē 。', '这么近，用不着坐车。', 'Gần vậy, không cần đi xe.', '"用不着" nghĩa là "không cần đến", diễn tả một việc/vật không cần thiết trong tình huống cụ thể.', 8);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 17, '竟然 - thế mà, lại', 'tā jìng rán yì fēn qián dōu méi huā jiù dào le bó lín 。', '他竟然一分钱都没花就到了柏林。', 'Anh ấy thế mà không tốn một xu nào đã đến được Berlin.', '"竟然" nghĩa là "thế mà, lại", đặt trước động từ để thể hiện sự NGẠC NHIÊN của người nói trước một kết quả không ngờ tới.', 9);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 17, 'Câu chữ 由 - do, bởi', 'zhè cì lǚ xíng wán quán yóu mò shēng rén de bāng zhù wán chéng 。', '这次旅行完全由陌生人的帮助完成。', 'Chuyến đi này hoàn toàn được hoàn thành nhờ sự giúp đỡ của người lạ.', 'Câu chữ "由" nghĩa là "do, bởi", dùng để chỉ rõ AI/CÁI GÌ chịu trách nhiệm thực hiện một việc, thường trang trọng hơn cách nói thông thường.', 10);
INSERT INTO grammar_patterns (course_id, module_index, pattern, pinyin, example_zh, example_vi, explanation, order_index) VALUES (12, 17, '一+V/Adj - vừa mới...', 'tā yí lù dā chē ， yí lù rèn shi xīn péng yǒu 。', '他一路搭车，一路认识新朋友。', 'Anh ấy vừa đi nhờ xe, vừa quen thêm bạn mới trên đường.', '"一 + động từ/tính từ" mang nghĩa "vừa mới...", diễn tả một hành động/trạng thái vừa mới xảy ra hoặc chỉ diễn ra trong chốc lát.', 11);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 0, '你好！', 'Nǐ hǎo!', 'Xin chào!', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 0, '您好！', 'Nín hǎo!', 'Xin chào ạ! (lịch sự)', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 0, '老师好！', 'Lǎoshī hǎo!', 'Chào thầy/cô ạ!', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 0, '谢谢你！', 'Xièxie nǐ!', 'Cảm ơn bạn!', 3);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 0, '你是哪国人？', 'Nǐ shì nǎ guó rén?', 'Bạn là người nước nào?', 4);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 0, '我是越南人。', 'Wǒ shì Yuènán rén.', 'Tôi là người Việt Nam.', 5);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 0, '他是中国人吗？', 'Tā shì Zhōngguó rén ma?', 'Anh ấy có phải người Trung Quốc không?', 6);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 0, '我是学生，你呢？', 'Wǒ shì xuésheng, nǐ ne?', 'Tôi là học sinh, còn bạn?', 7);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 0, '你叫什么名字？', 'Nǐ jiào shénme míngzi?', 'Bạn tên là gì?', 8);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 0, '我叫马丁。', 'Wǒ jiào Mǎdīng.', 'Tôi tên là Martin.', 9);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 0, '认识你很高兴。', 'Rènshi nǐ hěn gāoxìng.', 'Rất vui được quen biết bạn.', 10);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 0, '请问，您贵姓？', 'Qǐngwèn, nín guìxìng?', 'Xin hỏi, quý danh của ngài là gì?', 11);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 1, '你学习法语吗？', 'Nǐ xuéxí Fǎyǔ ma?', 'Bạn có học tiếng Pháp không?', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 1, '我不学习法语，我学习汉语。', 'Wǒ bù xuéxí Fǎyǔ, wǒ xuéxí Hànyǔ.', 'Tôi không học tiếng Pháp, tôi học tiếng Hán.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 1, '他也是学生。', 'Tā yě shì xuésheng.', 'Anh ấy cũng là học sinh.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 1, '我们都学习汉语。', 'Wǒmen dōu xuéxí Hànyǔ.', 'Chúng tôi đều học tiếng Hán.', 3);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 1, '你家有几口人？', 'Nǐ jiā yǒu jǐ kǒu rén?', 'Nhà bạn có mấy người?', 4);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 1, '我家有四口人：爸爸、妈妈、哥哥和我。', 'Wǒ jiā yǒu sì kǒu rén: bàba, māma, gēge hé wǒ.', 'Nhà tôi có bốn người: bố, mẹ, anh trai và tôi.', 5);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 1, '我有两个妹妹。', 'Wǒ yǒu liǎng ge mèimei.', 'Tôi có hai em gái.', 6);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 1, '他家没有姐姐。', 'Tā jiā méiyǒu jiějie.', 'Nhà anh ấy không có chị gái.', 7);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 1, '香蕉多少钱一斤？', 'Xiāngjiāo duōshao qián yì jīn?', 'Chuối bao nhiêu tiền một cân?', 8);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 1, '三块钱一斤。', 'Sān kuài qián yì jīn.', 'Ba đồng một cân.', 9);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 1, '我想买两斤苹果。', 'Wǒ xiǎng mǎi liǎng jīn píngguǒ.', 'Tôi muốn mua hai cân táo.', 10);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 1, '这个水果很贵。', 'Zhège shuǐguǒ hěn guì.', 'Loại hoa quả này rất đắt.', 11);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 2, '中国银行在哪儿？', 'Zhōngguó Yínháng zài nǎr?', 'Ngân hàng Trung Quốc ở đâu?', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 2, '银行在学校前边。', 'Yínháng zài xuéxiào qiánbian.', 'Ngân hàng ở phía trước trường học.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 2, '医院在银行旁边。', 'Yīyuàn zài yínháng pángbiān.', 'Bệnh viện ở bên cạnh ngân hàng.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 2, '附近有银行吗？', 'Fùjìn yǒu yínháng ma?', 'Gần đây có ngân hàng không?', 3);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 2, '今天几号？', 'Jīntiān jǐ hào?', 'Hôm nay ngày mấy?', 4);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 2, '今天九月三号，星期五。', 'Jīntiān jiǔyuè sān hào, xīngqīwǔ.', 'Hôm nay là ngày 3 tháng 9, thứ sáu.', 5);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 2, '你的生日是几月几号？', 'Nǐ de shēngrì shì jǐ yuè jǐ hào?', 'Sinh nhật bạn là ngày mấy tháng mấy?', 6);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 2, '明天是星期六，对吗？', 'Míngtiān shì xīngqīliù, duì ma?', 'Ngày mai là thứ bảy, đúng không?', 7);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 2, '你今天有什么安排？', 'Nǐ jīntiān yǒu shénme ānpái?', 'Hôm nay bạn có kế hoạch gì?', 8);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 2, '我上午上课，下午去图书馆。', 'Wǒ shàngwǔ shàngkè, xiàwǔ qù túshūguǎn.', 'Tôi học buổi sáng, chiều đi thư viện.', 9);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 2, '下课以后，我先吃饭，然后回家。', 'Xiàkè yǐhòu, wǒ xiān chīfàn, ránhòu huíjiā.', 'Sau khi tan học, tôi ăn cơm trước, sau đó về nhà.', 10);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 2, '晚上你做什么？', 'Wǎnshang nǐ zuò shénme?', 'Buổi tối bạn làm gì?', 11);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 3, '这个星期天你忙不忙？', 'Zhège xīngqītiān nǐ máng bu máng?', 'Chủ nhật này bạn có bận không?', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 3, '我不忙，想休息一下。', 'Wǒ bù máng, xiǎng xiūxi yíxià.', 'Tôi không bận, muốn nghỉ ngơi một chút.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 3, '你累不累？', 'Nǐ lèi bu lèi?', 'Bạn có mệt không?', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 3, '我们一起看电影，怎么样？', 'Wǒmen yìqǐ kàn diànyǐng, zěnmeyàng?', 'Chúng ta cùng xem phim nhé, thế nào?', 3);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 3, '你在哪儿吃饭？', 'Nǐ zài nǎr chīfàn?', 'Bạn ăn cơm ở đâu?', 4);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 3, '我在学校食堂吃饭。', 'Wǒ zài xuéxiào shítáng chīfàn.', 'Tôi ăn cơm ở căng tin trường.', 5);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 3, '食堂的菜很好吃。', 'Shítáng de cài hěn hǎochī.', 'Món ăn ở căng tin rất ngon.', 6);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 3, '谢谢！——不用谢。', 'Xièxie! — Búyòng xiè.', 'Cảm ơn! — Không có gì.', 7);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 3, '你要茶还是咖啡？', 'Nǐ yào chá háishi kāfēi?', 'Bạn muốn trà hay cà phê?', 8);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 3, '我要一杯咖啡。', 'Wǒ yào yì bēi kāfēi.', 'Tôi muốn một cốc cà phê.', 9);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 3, '咖啡要加糖吗？', 'Kāfēi yào jiā táng ma?', 'Cà phê có cần thêm đường không?', 10);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 3, '我喜欢喝茶，不喜欢喝咖啡。', 'Wǒ xǐhuan hē chá, bù xǐhuan hē kāfēi.', 'Tôi thích uống trà, không thích uống cà phê.', 11);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 4, '我已经搬家了。', 'Wǒ yǐjīng bānjiā le.', 'Tôi đã chuyển nhà rồi.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 4, '新房子怎么样？', 'Xīn fángzi zěnmeyàng?', 'Nhà mới thế nào?', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 4, '新房子很大，房间也很多。', 'Xīn fángzi hěn dà, fángjiān yě hěn duō.', 'Nhà mới rất to, phòng cũng nhiều.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 4, '你怎么知道我搬家了？', 'Nǐ zěnme zhīdào wǒ bānjiā le?', 'Sao bạn biết tôi chuyển nhà vậy?', 3);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 4, '我买了一件毛衣。', 'Wǒ mǎile yí jiàn máoyī.', 'Tôi đã mua một cái áo len.', 4);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 4, '这件毛衣什么颜色？', 'Zhè jiàn máoyī shénme yánsè?', 'Áo len này màu gì?', 5);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 4, '这件毛衣很漂亮，我很喜欢。', 'Zhè jiàn máoyī hěn piàoliang, wǒ hěn xǐhuan.', 'Áo len này rất đẹp, tôi rất thích.', 6);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 4, '你今天穿的衣服很好看。', 'Nǐ jīntiān chuān de yīfu hěn hǎokàn.', 'Quần áo bạn mặc hôm nay rất đẹp.', 7);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 4, '大学生可以打工吗？', 'Dàxuéshēng kěyǐ dǎgōng ma?', 'Sinh viên đại học có thể đi làm thêm không?', 8);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 4, '可以，但是不能影响学习。', 'Kěyǐ, dànshì bù néng yǐngxiǎng xuéxí.', 'Có thể, nhưng không được ảnh hưởng việc học.', 9);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 4, '打工可以赚钱，也可以有经验。', 'Dǎgōng kěyǐ zhuànqián, yě kěyǐ yǒu jīngyàn.', 'Làm thêm có thể kiếm tiền, cũng có thể có kinh nghiệm.', 10);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 4, '我周末在公司打工。', 'Wǒ zhōumò zài gōngsī dǎgōng.', 'Cuối tuần tôi làm thêm ở công ty.', 11);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 5, '我想送他一件礼物。', 'Wǒ xiǎng sòng tā yí jiàn lǐwù.', 'Tôi muốn tặng anh ấy một món quà.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 5, '今天是他的生日。', 'Jīntiān shì tā de shēngrì.', 'Hôm nay là sinh nhật của anh ấy.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 5, '祝你生日快乐！', 'Zhù nǐ shēngrì kuàilè!', 'Chúc bạn sinh nhật vui vẻ!', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 5, '我给她买了一束花。', 'Wǒ gěi tā mǎile yí shù huā.', 'Tôi đã mua cho cô ấy một bó hoa.', 3);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 5, '我口语和听力都很好。', 'Wǒ kǒuyǔ hé tīnglì dōu hěn hǎo.', 'Nói và nghe của tôi đều tốt.', 4);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 5, '我的阅读水平不太好。', 'Wǒ de yuèdú shuǐpíng bú tài hǎo.', 'Trình độ đọc hiểu của tôi không tốt lắm.', 5);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 5, '努力学习才能进步。', 'Nǔlì xuéxí cái néng jìnbù.', 'Chăm chỉ học tập mới có thể tiến bộ.', 6);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 5, '我想提高我的写作水平。', 'Wǒ xiǎng tígāo wǒ de xiězuò shuǐpíng.', 'Tôi muốn nâng cao trình độ viết của mình.', 7);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 5, '我上了四个小时的网。', 'Wǒ shàngle sì ge xiǎoshí de wǎng.', 'Tôi đã lên mạng bốn tiếng.', 8);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 5, '我的眼睛很累。', 'Wǒ de yǎnjing hěn lèi.', 'Mắt tôi rất mỏi.', 9);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 5, '你在手机上看什么视频？', 'Nǐ zài shǒujī shang kàn shénme shìpín?', 'Bạn đang xem video gì trên điện thoại?', 10);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 5, '少玩游戏，多休息。', 'Shǎo wán yóuxì, duō xiūxi.', 'Chơi game ít thôi, nghỉ ngơi nhiều hơn.', 11);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 6, '暖气还没有修好。', 'Nuǎnqì hái méiyǒu xiūhǎo.', 'Lò sưởi vẫn chưa sửa xong.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 6, '房间里很冷。', 'Fángjiān lǐ hěn lěng.', 'Trong phòng rất lạnh.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 6, '我给师傅打了两遍电话。', 'Wǒ gěi shīfu dǎle liǎng biàn diànhuà.', 'Tôi đã gọi điện cho thợ hai lần.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 6, '暖气坏了，我们只好去图书馆学习。', 'Nuǎnqì huàile, wǒmen zhǐhǎo qù túshūguǎn xuéxí.', 'Lò sưởi hỏng rồi, chúng tôi đành phải đi thư viện học.', 3);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 6, '快餐可以送到家里。', 'Kuàicān kěyǐ sòngdào jiā lǐ.', 'Đồ ăn nhanh có thể giao đến tận nhà.', 4);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 6, '我想点一份外卖。', 'Wǒ xiǎng diǎn yí fèn wàimài.', 'Tôi muốn gọi một suất đồ ăn giao hàng.', 5);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 6, '大概三十分钟能送到。', 'Dàgài sānshí fēnzhōng néng sòngdào.', 'Khoảng ba mươi phút là giao đến.', 6);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 6, '点外卖又方便又快。', 'Diǎn wàimài yòu fāngbiàn yòu kuài.', 'Gọi đồ ăn giao hàng vừa tiện vừa nhanh.', 7);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 6, '我把袋子放在桌子上了。', 'Wǒ bǎ dàizi fàng zài zhuōzi shàng le.', 'Tôi đã đặt cái túi lên bàn.', 8);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 6, '你的椅子跟我的不一样。', 'Nǐ de yǐzi gēn wǒ de bù yíyàng.', 'Ghế của bạn khác ghế của tôi.', 9);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 6, '我在找我的东西。', 'Wǒ zài zhǎo wǒ de dōngxi.', 'Tôi đang tìm đồ của mình.', 10);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 6, '请把门关上，好吗？', 'Qǐng bǎ mén guānshàng, hǎo ma?', 'Làm ơn đóng cửa lại được không?', 11);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 7, '我的自行车是红色的。', 'Wǒ de zìxíngchē shì hóngsè de.', 'Xe đạp của tôi màu đỏ.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 7, '这辆自行车有点儿旧了。', 'Zhè liàng zìxíngchē yǒudiǎnr jiù le.', 'Chiếc xe đạp này hơi cũ rồi.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 7, '你喜欢骑自行车吗？', 'Nǐ xǐhuan qí zìxíngchē ma?', 'Bạn có thích đi xe đạp không?', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 7, '算了，我们坐公交车吧。', 'Suànle, wǒmen zuò gōngjiāochē ba.', 'Thôi bỏ đi, chúng ta đi xe buýt vậy.', 3);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 7, '今年冬天变冷了。', 'Jīnnián dōngtiān biàn lěng le.', 'Mùa đông năm nay lạnh hơn.', 4);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 7, '今天天气怎么样？', 'Jīntiān tiānqì zěnmeyàng?', 'Thời tiết hôm nay thế nào?', 5);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 7, '还可以，不太冷。', 'Hái kěyǐ, bú tài lěng.', 'Cũng tạm được, không lạnh lắm.', 6);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 7, '北方冬天常常下雪。', 'Běifāng dōngtiān chángcháng xiàxuě.', 'Miền Bắc mùa đông thường có tuyết rơi.', 7);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 7, '妈妈给我寄来了礼物。', 'Māma gěi wǒ jìláile lǐwù.', 'Mẹ đã gửi quà đến cho tôi.', 8);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 7, '我收到了一个包裹。', 'Wǒ shōudàole yí ge bāoguǒ.', 'Tôi đã nhận được một bưu kiện.', 9);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 7, '打开包裹，我很惊喜。', 'Dǎkāi bāoguǒ, wǒ hěn jīngxǐ.', 'Mở bưu kiện ra, tôi rất bất ngờ.', 10);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 7, '我很想念家人。', 'Wǒ hěn xiǎngniàn jiārén.', 'Tôi rất nhớ người thân.', 11);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 8, '我听不懂他们说的话。', 'Wǒ tīng bu dǒng tāmen shuō de huà.', 'Tôi không hiểu họ nói gì.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 8, '他说方言，我听不懂。', 'Tā shuō fāngyán, wǒ tīng bu dǒng.', 'Anh ấy nói tiếng địa phương, tôi không hiểu.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 8, '请你说慢一点儿。', 'Qǐng nǐ shuō màn yìdiǎnr.', 'Xin bạn nói chậm hơn một chút.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 8, '请再说一遍，好吗？', 'Qǐng zài shuō yí biàn, hǎo ma?', 'Xin nói lại một lần nữa được không?', 3);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 8, '圣诞节快到了。', 'Shèngdànjié kuài dào le.', 'Giáng sinh sắp đến rồi.', 4);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 8, '我们在准备圣诞礼物。', 'Wǒmen zài zhǔnbèi Shèngdàn lǐwù.', 'Chúng tôi đang chuẩn bị quà Giáng sinh.', 5);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 8, '大家都很喜欢这个节日。', 'Dàjiā dōu hěn xǐhuan zhège jiérì.', 'Mọi người đều rất thích ngày lễ này.', 6);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 8, '要是你有空，一起来聚会吧。', 'Yàoshi nǐ yǒu kòng, yìqǐ lái jùhuì ba.', 'Nếu bạn có thời gian, cùng đến tụ họp nhé.', 7);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 8, '我正在看电视呢。', 'Wǒ zhèngzài kàn diànshì ne.', 'Tôi đang xem tivi.', 8);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 8, '他一边看电视一边吃饭。', 'Tā yìbiān kàn diànshì yìbiān chīfàn.', 'Anh ấy vừa xem tivi vừa ăn cơm.', 9);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 8, '这个节目很有意思。', 'Zhège jiémù hěn yǒuyìsi.', 'Chương trình này rất thú vị.', 10);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 8, '请安静一点儿，我在看新闻。', 'Qǐng ānjìng yìdiǎnr, wǒ zài kàn xīnwén.', 'Xin yên tĩnh một chút, tôi đang xem tin tức.', 11);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 9, '长城有八千八百五十多公里。', 'Chángchéng yǒu bāqiān bābǎi wǔshí duō gōnglǐ.', 'Vạn Lý Trường Thành dài hơn 8850km.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 9, '长城是世界著名的历史古迹。', 'Chángchéng shì shìjiè zhùmíng de lìshǐ gǔjì.', 'Trường Thành là di tích lịch sử nổi tiếng thế giới.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 9, '长城是古代建的。', 'Chángchéng shì gǔdài jiàn de.', 'Trường Thành được xây từ thời cổ đại.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 9, '我很想去长城看看。', 'Wǒ hěn xiǎng qù Chángchéng kànkan.', 'Tôi rất muốn đi thăm Trường Thành.', 3);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 9, '晚会开得非常成功。', 'Wǎnhuì kāi de fēicháng chénggōng.', 'Buổi tiệc rất thành công.', 4);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 9, '大家都唱歌跳舞，气氛很热闹。', 'Dàjiā dōu chànggē tiàowǔ, qìfēn hěn rènao.', 'Mọi người đều hát và nhảy múa, không khí rất náo nhiệt.', 5);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 9, '这个表演很精彩。', 'Zhège biǎoyǎn hěn jīngcǎi.', 'Tiết mục biểu diễn này rất hay.', 6);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 9, '晚会可能九点结束。', 'Wǎnhuì kěnéng jiǔ diǎn jiéshù.', 'Buổi tiệc có lẽ kết thúc lúc chín giờ.', 7);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 9, '我当过英语老师。', 'Wǒ dāngguo Yīngyǔ lǎoshī.', 'Tôi từng là giáo viên tiếng Anh.', 8);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 9, '那段经历有意思极了。', 'Nà duàn jīnglì yǒuyìsi jíle.', 'Trải nghiệm đó cực kỳ thú vị.', 9);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 9, '你以前做过什么工作？', 'Nǐ yǐqián zuòguo shénme gōngzuò?', 'Trước đây bạn từng làm công việc gì?', 10);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 9, '当我在中国工作的时候，认识了很多朋友。', 'Dāng wǒ zài Zhōngguó gōngzuò de shíhou, rènshile hěn duō péngyou.', 'Khi tôi làm việc ở Trung Quốc, tôi đã quen được nhiều bạn.', 11);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 10, '一个人到了新的地方，要入乡随俗。', 'Yí ge rén dàole xīn de dìfang, yào rù xiāng suí sú.', 'Một người đến nơi mới thì phải nhập gia tùy tục.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 10, '我今天渐渐习惯这里的生活了。', 'Wǒ jīntiān jiànjiàn xíguàn zhèlǐ de shēnghuó le.', 'Hôm nay tôi dần quen với cuộc sống ở đây rồi.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 10, '对不起，我迟到了。', 'Duìbuqǐ, wǒ chídào le.', 'Xin lỗi, tôi đến muộn rồi.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 10, '为了不迟到，我每天都定闹钟。', 'Wèile bù chídào, wǒ měitiān dōu dìng nàozhōng.', 'Để không đến muộn, mỗi ngày tôi đều đặt báo thức.', 3);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 10, '儿子要回家了，妈妈很激动。', 'Érzi yào huíjiā le, māma hěn jīdòng.', 'Con trai sắp về nhà rồi, mẹ rất xúc động.', 4);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 10, '我从来没有这么想家过。', 'Wǒ cónglái méiyǒu zhème xiǎngjiā guo.', 'Tôi chưa bao giờ nhớ nhà đến thế.', 5);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 10, '爸爸去机场接儿子。', 'Bàba qù jīchǎng jiē érzi.', 'Bố đi sân bay đón con trai.', 6);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 10, '放假了，全家终于可以团聚了。', 'Fàngjià le, quánjiā zhōngyú kěyǐ tuánjù le.', 'Nghỉ lễ rồi, cả nhà cuối cùng cũng có thể sum họp.', 7);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 10, '市场上有一个卖辣椒的女孩儿。', 'Shìchǎng shàng yǒu yí ge mài làjiāo de nǚháir.', 'Ở chợ có một cô gái bán ớt.', 8);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 10, '她的辣椒很新鲜。', 'Tā de làjiāo hěn xīnxiān.', 'Ớt của cô ấy rất tươi.', 9);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 10, '她既聪明又勤劳，生意很好。', 'Tā jì cōngming yòu qínláo, shēngyi hěn hǎo.', 'Cô ấy vừa thông minh vừa chăm chỉ, buôn bán rất tốt.', 10);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 10, '这斤辣椒多少钱？', 'Zhè jīn làjiāo duōshao qián?', 'Cân ớt này bao nhiêu tiền?', 11);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 11, '我和中国有个约会。', 'Wǒ hé Zhōngguó yǒu ge yuēhuì.', 'Tôi có một cuộc hẹn với Trung Quốc.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 11, '这是我实现梦想的机会。', 'Zhè shì wǒ shíxiàn mèngxiǎng de jīhuì.', 'Đây là cơ hội để tôi thực hiện ước mơ.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 11, '我决定来中国留学。', 'Wǒ juédìng lái Zhōngguó liúxué.', 'Tôi quyết định đến Trung Quốc du học.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 11, '中国文化不但有意思，而且很丰富。', 'Zhōngguó wénhuà búdàn yǒuyìsi, érqiě hěn fēngfù.', 'Văn hóa Trung Quốc không những thú vị mà còn rất phong phú.', 3);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 11, '为什么我一个人站着吃？', 'Wèishénme wǒ yí ge rén zhànzhe chī?', 'Vì sao tôi đứng ăn một mình?', 4);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 11, '餐厅里的座位都满了。', 'Cāntīng lǐ de zuòwèi dōu mǎn le.', 'Chỗ ngồi trong nhà hàng đã đầy hết rồi.', 5);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 11, '这个习俗很奇怪，但是也有原因。', 'Zhège xísú hěn qíguài, dànshì yě yǒu yuányīn.', 'Phong tục này khá lạ, nhưng cũng có nguyên nhân.', 6);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 11, '你能给我解释一下吗？', 'Nǐ néng gěi wǒ jiěshì yíxià ma?', 'Bạn có thể giải thích cho tôi một chút không?', 7);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 11, '妈妈，我这里一切都好，请放心。', 'Māma, wǒ zhèlǐ yíqiè dōu hǎo, qǐng fàngxīn.', 'Mẹ ơi, ở đây con mọi thứ đều tốt, mẹ yên tâm nhé.', 8);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 11, '我越来越适应这里的生活了。', 'Wǒ yuè lái yuè shìyìng zhèlǐ de shēnghuó le.', 'Con càng ngày càng thích nghi với cuộc sống ở đây.', 9);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 11, '不要担心我，我能照顾好自己。', 'Búyào dānxīn wǒ, wǒ néng zhàogù hǎo zìjǐ.', 'Đừng lo cho con, con có thể tự chăm sóc tốt bản thân.', 10);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 11, '我会常常写信报平安的。', 'Wǒ huì chángcháng xiěxìn bào píng''ān de.', 'Con sẽ thường xuyên viết thư báo bình an.', 11);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 12, '我要去埃及旅行。', 'Wǒ yào qù Āijí lǚxíng.', 'Tôi sẽ đi du lịch Ai Cập.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 12, '我已经办好了签证和护照。', 'Wǒ yǐjīng bànhǎole qiānzhèng hé hùzhào.', 'Tôi đã làm xong visa và hộ chiếu.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 12, '金字塔是世界历史奇迹。', 'Jīnzìtǎ shì shìjiè lìshǐ qíjì.', 'Kim tự tháp là kỳ tích lịch sử thế giới.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 12, '一个人旅行要小心一点儿。', 'Yí ge rén lǚxíng yào xiǎoxīn yìdiǎnr.', 'Du lịch một mình phải cẩn thận hơn.', 3);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 12, '回到故乡，我想起了童年的旧梦。', 'Huídào gùxiāng, wǒ xiǎngqǐle tóngnián de jiùmèng.', 'Về đến quê hương, tôi nhớ lại giấc mơ tuổi thơ.', 4);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 12, '这里的变化比我想的还大。', 'Zhèlǐ de biànhuà bǐ wǒ xiǎng de hái dà.', 'Sự thay đổi ở đây còn lớn hơn tôi nghĩ.', 5);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 12, '熟悉的地方现在变得有点儿陌生了。', 'Shúxī de dìfang xiànzài biàn de yǒudiǎnr mòshēng le.', 'Nơi quen thuộc giờ trở nên hơi xa lạ.', 6);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 12, '时光过得真快。', 'Shíguāng guò de zhēn kuài.', 'Thời gian trôi qua thật nhanh.', 7);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 12, '爱的教育比严格的教育更有效。', 'Ài de jiàoyù bǐ yángé de jiàoyù gèng yǒuxiào.', 'Giáo dục bằng tình yêu thương hiệu quả hơn giáo dục nghiêm khắc.', 8);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 12, '老师对学生特别有耐心。', 'Lǎoshī duì xuésheng tèbié yǒu nàixīn.', 'Thầy cô rất kiên nhẫn với học sinh.', 9);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 12, '理解不如尊重重要。', 'Lǐjiě bùrú zūnzhòng zhòngyào.', 'Thấu hiểu không quan trọng bằng tôn trọng.', 10);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 12, '父母是孩子最好的榜样。', 'Fùmǔ shì háizi zuì hǎo de bǎngyàng.', 'Cha mẹ là tấm gương tốt nhất của con cái.', 11);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 13, '快乐，其实很简单。', 'Kuàilè, qíshí hěn jiǎndān.', 'Hạnh phúc thực ra rất đơn giản.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 13, '学会知足，就会更快乐。', 'Xuéhuì zhīzú, jiù huì gèng kuàilè.', 'Học cách biết đủ, sẽ hạnh phúc hơn.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 13, '珍惜现在拥有的一切。', 'Zhēnxī xiànzài yōngyǒu de yíqiè.', 'Trân trọng tất cả những gì đang có.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 13, '一个微笑就能带来幸福。', 'Yí ge wēixiào jiù néng dàilái xìngfú.', 'Một nụ cười thôi cũng có thể mang lại hạnh phúc.', 3);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 13, '我在书本里发现了一只小蚂蚁。', 'Wǒ zài shūběn lǐ fāxiànle yì zhī xiǎo mǎyǐ.', 'Tôi phát hiện một con kiến nhỏ trong sách.', 4);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 13, '这只蚂蚁在书页上爬来爬去。', 'Zhè zhī mǎyǐ zài shūyè shang pá lái pá qù.', 'Con kiến này bò tới bò lui trên trang sách.', 5);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 13, '我好奇地仔细观察它。', 'Wǒ hàoqí de zǐxì guānchá tā.', 'Tôi tò mò quan sát nó thật kỹ.', 6);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 13, '小小的蚂蚁也有它自己的世界。', 'Xiǎoxiǎo de mǎyǐ yě yǒu tā zìjǐ de shìjiè.', 'Con kiến nhỏ bé cũng có thế giới riêng của nó.', 7);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 13, '他说的是"枕头"，不是"针头"。', 'Tā shuō de shì "zhěntou", bú shì "zhēntóu".', 'Anh ấy nói là “gối”, không phải “đầu kim”.', 8);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 13, '因为声调不对，造成了误会。', 'Yīnwèi shēngdiào bú duì, zàochéngle wùhuì.', 'Vì thanh điệu sai nên gây ra hiểu lầm.', 9);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 13, '这个笑话让大家都笑了。', 'Zhège xiàohua ràng dàjiā dōu xiào le.', 'Chuyện cười này khiến mọi người đều cười.', 10);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 13, '请你帮我纠正一下发音。', 'Qǐng nǐ bāng wǒ jiūzhèng yíxià fāyīn.', 'Xin bạn giúp tôi sửa lại phát âm một chút.', 11);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 14, '中国来信改变了我的生活。', 'Zhōngguó láixìn gǎibiànle wǒ de shēnghuó.', 'Lá thư từ Trung Quốc đã thay đổi cuộc đời tôi.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 14, '除了学习汉语，我还了解了中国文化。', 'Chúle xuéxí Hànyǔ, wǒ hái liǎojiěle Zhōngguó wénhuà.', 'Ngoài học tiếng Hán, tôi còn hiểu thêm về văn hóa Trung Quốc.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 14, '这封信让我很感动。', 'Zhè fēng xìn ràng wǒ hěn gǎndòng.', 'Lá thư này khiến tôi rất cảm động.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 14, '我们一直保持着联系。', 'Wǒmen yìzhí bǎochízhe liánxì.', 'Chúng tôi vẫn luôn giữ liên lạc.', 3);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 14, '这是我第一次打的。', 'Zhè shì wǒ dì-yī cì dǎdī.', 'Đây là lần đầu tiên tôi đi taxi.', 4);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 14, '路上堵车，我有点儿紧张。', 'Lùshang dǔchē, wǒ yǒudiǎnr jǐnzhāng.', 'Đường tắc, tôi hơi hồi hộp.', 5);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 14, '幸好司机走的路线很安全。', 'Xìnghǎo sījī zǒu de lùxiàn hěn ānquán.', 'May mà tuyến đường tài xế đi rất an toàn.', 6);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 14, '请问，到机场多少钱？', 'Qǐngwèn, dào jīchǎng duōshao qián?', 'Xin hỏi, đến sân bay bao nhiêu tiền?', 7);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 14, '这只信鸽飞了很远的距离才回来。', 'Zhè zhī xìngē fēile hěn yuǎn de jùlí cái huílái.', 'Con bồ câu này bay một quãng đường rất xa mới về được.', 8);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 14, '信鸽靠本能认路，真神奇。', 'Xìngē kào běnnéng rènlù, zhēn shénqí.', 'Bồ câu dựa vào bản năng để nhận đường, thật kỳ diệu.', 9);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 14, '经过训练，它能准确地飞回家。', 'Jīngguò xùnliàn, tā néng zhǔnquè de fēi huíjiā.', 'Qua huấn luyện, nó có thể bay về nhà một cách chính xác.', 10);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 14, '这真是一个奇迹。', 'Zhè zhēnshi yí ge qíjì.', 'Đây thực sự là một kỳ tích.', 11);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 15, '他把表拨快三分钟，这样就不会迟到了。', 'Tā bǎ biǎo bō kuài sān fēnzhōng, zhèyàng jiù bú huì chídào le.', 'Anh ấy vặn đồng hồ nhanh lên ba phút, như vậy sẽ không đến muộn.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 15, '为了准时，他养成了提前出门的习惯。', 'Wèile zhǔnshí, tā yǎngchéngle tíqián chūmén de xíguàn.', 'Để đúng giờ, anh ấy đã tạo thói quen ra khỏi nhà sớm.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 15, '难道这个方法真的有用吗？', 'Nándào zhège fāngfǎ zhēnde yǒuyòng ma?', 'Chẳng lẽ phương pháp này thật sự có tác dụng sao?', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 15, '他总是很准时。', 'Tā zǒngshì hěn zhǔnshí.', 'Anh ấy luôn luôn đúng giờ.', 3);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 15, '我们约好六点见面。', 'Wǒmen yuēhǎo liù diǎn jiànmiàn.', 'Chúng tôi đã hẹn gặp nhau lúc sáu giờ.', 4);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 15, '尽管等了很久，她却一直没来。', 'Jǐnguǎn děngle hěn jiǔ, tā què yìzhí méi lái.', 'Mặc dù đã đợi rất lâu, cô ấy vẫn không đến.', 5);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 15, '你到底来不来约会？', 'Nǐ dàodǐ lái bu lái yuēhuì?', 'Rốt cuộc bạn có đến buổi hẹn không?', 6);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 15, '第一次约会，我很紧张。', 'Dì-yī cì yuēhuì, wǒ hěn jǐnzhāng.', 'Lần hẹn đầu tiên, tôi rất hồi hộp.', 7);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 15, '盲人朋友是靠听声音"看"电影的。', 'Mángrén péngyou shì kào tīng shēngyīn "kàn" diànyǐng de.', 'Người bạn khiếm thị ''xem'' phim bằng cách nghe âm thanh.', 8);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 15, '即使看不见画面，他也能想象出情节。', 'Jíshǐ kàn bu jiàn huàmiàn, tā yě néng xiǎngxiàng chū qíngjié.', 'Dù không nhìn thấy hình ảnh, anh ấy vẫn có thể tưởng tượng ra tình tiết.', 9);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 15, '这是一次特殊的观影感受。', 'Zhè shì yí cì tèshū de guānyǐng gǎnshòu.', 'Đây là một trải nghiệm xem phim đặc biệt.', 10);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 15, '他听得很认真，好像真的看见了似的。', 'Tā tīng de hěn rènzhēn, hǎoxiàng zhēnde kànjiànle shìde.', 'Anh ấy nghe rất chăm chú, giống như thật sự đã nhìn thấy vậy.', 11);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 16, '我有一个中国笔友。', 'Wǒ yǒu yí ge Zhōngguó bǐyǒu.', 'Tôi có một người bạn qua thư ở Trung Quốc.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 16, '我们经常写信交流。', 'Wǒmen jīngcháng xiěxìn jiāoliú.', 'Chúng tôi thường xuyên viết thư trao đổi.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 16, '只有坚持写信，才能保持这段友谊。', 'Zhǐyǒu jiānchí xiěxìn, cái néng bǎochí zhè duàn yǒuyì.', 'Chỉ có kiên trì viết thư mới giữ được tình bạn này.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 16, '这段友谊对我来说很珍贵。', 'Zhè duàn yǒuyì duì wǒ lái shuō hěn zhēnguì.', 'Tình bạn này đối với tôi rất quý báu.', 3);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 16, '人格和尊严比金钱更重要。', 'Réngé hé zūnyán bǐ jīnqián gèng zhòngyào.', 'Nhân cách và phẩm giá quan trọng hơn tiền bạc.', 4);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 16, '他拒绝了别人的施舍。', 'Tā jùjuéle biéren de shīshě.', 'Anh ấy đã từ chối sự bố thí của người khác.', 5);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 16, '每个人都应该受到尊重。', 'Měi ge rén dōu yīnggāi shòudào zūnzhòng.', 'Mỗi người đều nên được tôn trọng.', 6);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 16, '千万不要小看自己。', 'Qiānwàn búyào xiǎokàn zìjǐ.', 'Nhất định đừng xem thường bản thân.', 7);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 16, '愚公移山是一个有名的中国故事。', 'Yúgōng yíshān shì yí ge yǒumíng de Zhōngguó gùshi.', 'Ngu Công dời núi là một câu chuyện nổi tiếng của Trung Quốc.', 8);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 16, '不管别人怎么笑话他，愚公都不放弃。', 'Bùguǎn biéren zěnme xiàohua tā, Yúgōng dōu bú fàngqì.', 'Bất kể người khác cười nhạo thế nào, Ngu Công đều không từ bỏ.', 9);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 16, '他相信子孙后代能把山移走。', 'Tā xiāngxìn zǐsūn hòudài néng bǎ shān yízǒu.', 'Ông tin rằng con cháu đời sau có thể dời được núi.', 10);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 16, '坚持不懈才能成功。', 'Jiānchí búxiè cái néng chénggōng.', 'Kiên trì không ngừng mới có thể thành công.', 11);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '现在用卡很方便，不必带很多现金。', 'Xiànzài yòng kǎ hěn fāngbiàn, búbì dài hěn duō xiànjīn.', 'Bây giờ dùng thẻ rất tiện, không cần mang nhiều tiền mặt.', 0);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '只要刷一下卡，就能上车。', 'Zhǐyào shuā yíxià kǎ, jiù néng shàngchē.', 'Chỉ cần quẹt thẻ một cái là có thể lên xe.', 1);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '我的公交卡该充值了。', 'Wǒ de gōngjiāokǎ gāi chōngzhí le.', 'Thẻ xe buýt của tôi cần nạp tiền rồi.', 2);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '既然你有信用卡，就不用带现金了。', 'Jìrán nǐ yǒu xìnyòngkǎ, jiù búyòng dài xiànjīn le.', 'Đã có thẻ tín dụng rồi thì không cần mang tiền mặt nữa.', 3);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '我一直坚持"低碳生活"。', 'Wǒ yìzhí jiānchí "dītàn shēnghuó".', 'Tôi luôn kiên trì lối sống ''ít carbon''.', 4);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '骑车上班既环保又健康。', 'Qíchē shàngbān jì huánbǎo yòu jiànkāng.', 'Đi xe đạp đi làm vừa bảo vệ môi trường vừa khỏe mạnh.', 5);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '垃圾分类可以节约资源。', 'Lājī fēnlèi kěyǐ jiéyuē zīyuán.', 'Phân loại rác có thể tiết kiệm tài nguyên.', 6);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '每个人都应该减少浪费。', 'Měi ge rén dōu yīnggāi jiǎnshǎo làngfèi.', 'Mỗi người đều nên giảm bớt lãng phí.', 7);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '父子俩一起爬长城。', 'Fùzǐ liǎ yìqǐ pá Chángchéng.', 'Hai cha con cùng leo Trường Thành.', 8);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '哪怕很累，他也坚持爬到了最高处。', 'Nǎpà hěn lèi, tā yě jiānchí pádàole zuì gāo chù.', 'Dù rất mệt, anh ấy vẫn kiên trì leo đến điểm cao nhất.', 9);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '万一走不动了，我们就休息一下。', 'Wànyī zǒu bu dòng le, wǒmen jiù xiūxi yíxià.', 'Lỡ như đi không nổi nữa thì chúng ta nghỉ một chút.', 10);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '爬上长城，他感到很骄傲。', 'Pá shàng Chángchéng, tā gǎndào hěn jiāo''ào.', 'Leo lên được Trường Thành, anh ấy cảm thấy rất tự hào.', 11);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '他决定搭车去柏林。', 'Tā juédìng dāchē qù Bólín.', 'Anh ấy quyết định đi nhờ xe đến Berlin.', 12);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '路上遇到了很多善良的陌生人。', 'Lùshang yùdàole hěn duō shànliáng de mòshēngrén.', 'Trên đường anh ấy gặp rất nhiều người lạ tốt bụng.', 13);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '这是一次难忘的冒险经历。', 'Zhè shì yí cì nánwàng de màoxiǎn jīnglì.', 'Đây là một trải nghiệm mạo hiểm khó quên.', 14);
INSERT INTO example_sentences (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '竟然一分钱都没花就到了目的地。', 'Jìngrán yì fēn qián dōu méi huā jiù dàole mùdìdì.', 'Thế mà không tốn một xu nào cũng đã đến được đích.', 15);
