INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 16, '写信交流', 'xiěxìn jiāoliú', 'viết thư trao đổi', 1);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 16, '珍贵的友谊', 'zhēnguì de yǒuyì', 'tình bạn quý báu', 2);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 16, '第一人格', 'dì-yī réngé', 'nhân cách bậc nhất', 3);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 16, '受到尊重', 'shòudào zūnzhòng', 'được tôn trọng', 4);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 16, '千万不要', 'qiānwàn búyào', 'nhất định đừng', 5);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 16, '愚公移山', 'Yúgōng yíshān', 'Ngu Công dời núi', 6);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 16, '坚持不懈', 'jiānchí búxiè', 'kiên trì không ngừng', 7);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 16, '不管...都', 'bùguǎn...dōu', 'bất kể...đều', 8);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '刷卡', 'shuākǎ', 'quẹt thẻ', 0);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '公交卡充值', 'gōngjiāokǎ chōngzhí', 'nạp tiền thẻ xe buýt', 1);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '不必带现金', 'búbì dài xiànjīn', 'không cần mang tiền mặt', 2);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '低碳生活', 'dītàn shēnghuó', 'cuộc sống ít carbon', 3);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '垃圾分类', 'lājī fēnlèi', 'phân loại rác', 4);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '节约资源', 'jiéyuē zīyuán', 'tiết kiệm tài nguyên', 5);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '父子俩', 'fùzǐ liǎ', 'hai cha con', 6);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '坚持爬到', 'jiānchí pádào', 'kiên trì leo đến', 7);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '感到骄傲', 'gǎndào jiāo''ào', 'cảm thấy tự hào', 8);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '搭车去柏林', 'dāchē qù Bólín', 'đi nhờ xe đến Berlin', 9);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '善良的陌生人', 'shànliáng de mòshēngrén', 'người lạ tốt bụng', 10);
INSERT INTO phrases (course_id, module_index, zh, pinyin, vi, order_index) VALUES (12, 17, '难忘的经历', 'nánwàng de jīnglì', 'trải nghiệm khó quên', 11);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 0, 1, '李一民', '你好！', 'Nǐ hǎo!', 'Xin chào!', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 0, 1, '阿明', '您好！', 'Nín hǎo!', 'Chào thầy/cô ạ!', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 0, 2, '山田', '你好！你是哪国人？', 'Nǐ hǎo! Nǐ shì nǎ guó rén?', 'Chào bạn! Bạn là người nước nào?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 0, 2, '阿明', '我是泰国人。你呢？', 'Wǒ shì Tàiguó rén. Nǐ ne?', 'Tôi là người Thái Lan. Còn bạn?', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 0, 2, '山田', '我是日本人。', 'Wǒ shì Rìběn rén.', 'Tôi là người Nhật Bản.', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 0, 3, '崔浩', '你好，你叫什么名字？', 'Nǐ hǎo, nǐ jiào shénme míngzi?', 'Chào bạn, bạn tên là gì?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 0, 3, '林娜', '我叫林娜。你呢？', 'Wǒ jiào Línnà. Nǐ ne?', 'Tôi tên là Linna. Còn bạn?', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 0, 3, '崔浩', '我叫崔浩。认识你很高兴。', 'Wǒ jiào Cuī Hào. Rènshi nǐ hěn gāoxìng.', 'Tôi tên là Thôi Hạo. Rất vui được quen bạn.', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 1, 1, '马丁', '你学习法语吗？', 'Nǐ xuéxí Fǎyǔ ma?', 'Bạn có học tiếng Pháp không?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 1, 1, '朱云', '不，我学习汉语。你呢？', 'Bù, wǒ xuéxí Hànyǔ. Nǐ ne?', 'Không, tôi học tiếng Hán. Còn bạn?', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 1, 1, '马丁', '我也学习汉语。', 'Wǒ yě xuéxí Hànyǔ.', 'Tôi cũng học tiếng Hán.', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 1, 2, '阿明', '你家有几口人？', 'Nǐ jiā yǒu jǐ kǒu rén?', 'Nhà bạn có mấy người?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 1, 2, '朱云', '我家有四口人：爸爸、妈妈、弟弟和我。', 'Wǒ jiā yǒu sì kǒu rén: bàba, māma, dìdi hé wǒ.', 'Nhà tôi có bốn người: bố, mẹ, em trai và tôi.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 1, 3, '朱云', '香蕉多少钱一斤？', 'Xiāngjiāo duōshao qián yì jīn?', 'Chuối bao nhiêu tiền một cân?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 1, 3, '卖水果的', '两块五一斤。', 'Liǎng kuài wǔ yì jīn.', 'Hai đồng rưỡi một cân.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 1, 3, '朱云', '好，我买三斤。', 'Hǎo, wǒ mǎi sān jīn.', 'Được, tôi mua ba cân.', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 2, 1, '马丁', '请问，中国银行在哪儿？', 'Qǐngwèn, Zhōngguó Yínháng zài nǎr?', 'Xin hỏi, ngân hàng Trung Quốc ở đâu?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 2, 1, '李一民', '在学校前边，医院旁边。', 'Zài xuéxiào qiánbian, yīyuàn pángbiān.', 'Ở phía trước trường học, bên cạnh bệnh viện.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 2, 1, '马丁', '谢谢您！', 'Xièxie nín!', 'Cảm ơn ngài!', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 2, 2, '山田', '今天几号？', 'Jīntiān jǐ hào?', 'Hôm nay ngày mấy?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 2, 2, '林娜', '今天九月三号，星期五。', 'Jīntiān jiǔyuè sān hào, xīngqīwǔ.', 'Hôm nay ngày 3 tháng 9, thứ sáu.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 2, 2, '山田', '啊，明天是我的生日！', 'À, míngtiān shì wǒ de shēngrì!', 'À, ngày mai là sinh nhật tôi!', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 2, 3, '崔浩', '你今天有什么安排？', 'Nǐ jīntiān yǒu shénme ānpái?', 'Hôm nay bạn có kế hoạch gì?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 2, 3, '马丁', '我先上课，然后去图书馆看书。', 'Wǒ xiān shàngkè, ránhòu qù túshūguǎn kànshū.', 'Tôi học trước, sau đó đi thư viện đọc sách.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 2, 3, '崔浩', '晚上一起吃饭，怎么样？', 'Wǎnshang yìqǐ chīfàn, zěnmeyàng?', 'Tối nay cùng ăn cơm nhé, thế nào?', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 3, 1, '林娜', '这个星期天你忙不忙？', 'Zhège xīngqītiān nǐ máng bu máng?', 'Chủ nhật này bạn có bận không?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 3, 1, '朱云', '不忙，我想休息一下。你呢？', 'Bù máng, wǒ xiǎng xiūxi yíxià. Nǐ ne?', 'Không bận, tôi muốn nghỉ ngơi. Còn bạn?', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 3, 1, '林娜', '我们一起去运动，怎么样？', 'Wǒmen yìqǐ qù yùndòng, zěnmeyàng?', 'Chúng ta cùng đi vận động nhé, thế nào?', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 3, 2, '阿明', '你在哪儿吃饭？', 'Nǐ zài nǎr chīfàn?', 'Bạn ăn cơm ở đâu?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 3, 2, '崔浩', '我在学校食堂吃饭，菜很好吃。', 'Wǒ zài xuéxiào shítáng chīfàn, cài hěn hǎochī.', 'Tôi ăn ở căng tin trường, món ăn rất ngon.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 3, 2, '阿明', '我们一起去吧！', 'Wǒmen yìqǐ qù ba!', 'Chúng ta cùng đi nhé!', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 3, 3, '服务员', '你要茶还是咖啡？', 'Nǐ yào chá háishi kāfēi?', 'Anh/chị muốn trà hay cà phê?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 3, 3, '马丁', '我要一杯咖啡，谢谢。', 'Wǒ yào yì bēi kāfēi, xièxie.', 'Tôi muốn một cốc cà phê, cảm ơn.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 3, 3, '服务员', '要加糖吗？', 'Yào jiā táng ma?', 'Có cần thêm đường không?', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 3, 3, '马丁', '不用，谢谢。', 'Búyòng, xièxie.', 'Không cần, cảm ơn.', 3);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 4, 1, '山田', '我已经搬家了。', 'Wǒ yǐjīng bānjiā le.', 'Tôi đã chuyển nhà rồi.', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 4, 1, '朱云', '是吗？新房子怎么样？', 'Shì ma? Xīn fángzi zěnmeyàng?', 'Vậy à? Nhà mới thế nào?', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 4, 1, '山田', '很大，也很新。', 'Hěn dà, yě hěn xīn.', 'Rất to, cũng rất mới.', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 4, 2, '林娜', '我买了一件毛衣，你看漂亮吗？', 'Wǒ mǎile yí jiàn máoyī, nǐ kàn piàoliang ma?', 'Tôi mua một cái áo len, bạn xem có đẹp không?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 4, 2, '朱云', '很漂亮！什么颜色？', 'Hěn piàoliang! Shénme yánsè?', 'Đẹp lắm! Màu gì vậy?', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 4, 2, '林娜', '红色的。', 'Hóngsè de.', 'Màu đỏ.', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 4, 3, '崔浩', '大学生可以打工吗？', 'Dàxuéshēng kěyǐ dǎgōng ma?', 'Sinh viên đại học có thể đi làm thêm không?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 4, 3, '马丁', '可以，但是不能影响学习。', 'Kěyǐ, dànshì bù néng yǐngxiǎng xuéxí.', 'Có thể, nhưng không được ảnh hưởng việc học.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 4, 3, '崔浩', '我也想打工，赚点儿钱。', 'Wǒ yě xiǎng dǎgōng, zhuàn diǎnr qián.', 'Tôi cũng muốn làm thêm, kiếm chút tiền.', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 5, 1, '阿明', '今天是马丁的生日，我想送他一件礼物。', 'Jīntiān shì Mǎdīng de shēngrì, wǒ xiǎng sòng tā yí jiàn lǐwù.', 'Hôm nay là sinh nhật Martin, tôi muốn tặng anh ấy quà.', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 5, 1, '朱云', '送什么呢？', 'Sòng shénme ne?', 'Tặng gì đây?', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 5, 1, '阿明', '送蛋糕还是巧克力，你说呢？', 'Sòng dàngāo háishi qiǎokèlì, nǐ shuō ne?', 'Tặng bánh kem hay sô-cô-la, bạn thấy sao?', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 5, 2, '老师', '你觉得你的汉语怎么样？', 'Nǐ juéde nǐ de Hànyǔ zěnmeyàng?', 'Em thấy tiếng Hán của mình thế nào?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 5, 2, '山田', '我口语和听力都很好，但是阅读不太好。', 'Wǒ kǒuyǔ hé tīnglì dōu hěn hǎo, dànshì yuèdú bú tài hǎo.', 'Nói và nghe của em đều tốt, nhưng đọc hiểu không tốt lắm.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 5, 2, '老师', '多读书就能提高。', 'Duō dúshū jiù néng tígāo.', 'Đọc sách nhiều sẽ tiến bộ thôi.', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 5, 3, '朱云', '你怎么这么累？', 'Nǐ zěnme zhème lèi?', 'Sao bạn mệt vậy?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 5, 3, '崔浩', '我上了四个小时的网，眼睛很累。', 'Wǒ shàngle sì ge xiǎoshí de wǎng, yǎnjing hěn lèi.', 'Tôi lên mạng bốn tiếng rồi, mắt rất mỏi.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 5, 3, '朱云', '你应该多休息。', 'Nǐ yīnggāi duō xiūxi.', 'Bạn nên nghỉ ngơi nhiều hơn.', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 6, 1, '马丁', '房间里怎么这么冷？', 'Fángjiān lǐ zěnme zhème lěng?', 'Sao trong phòng lạnh vậy?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 6, 1, '林娜', '暖气坏了，还没有修好。', 'Nuǎnqì huàile, hái méiyǒu xiūhǎo.', 'Lò sưởi hỏng rồi, vẫn chưa sửa xong.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 6, 1, '马丁', '打电话叫师傅来修吧。', 'Dǎ diànhuà jiào shīfu lái xiū ba.', 'Gọi điện gọi thợ đến sửa đi.', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 6, 2, '崔浩', '我们点外卖吧，快餐可以送到家里。', 'Wǒmen diǎn wàimài ba, kuàicān kěyǐ sòngdào jiā lǐ.', 'Chúng ta gọi đồ ăn giao hàng đi, đồ ăn nhanh có thể giao đến tận nhà.', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 6, 2, '马丁', '好啊，大概多久能送到？', 'Hǎo a, dàgài duōjiǔ néng sòngdào?', 'Được đấy, khoảng bao lâu thì giao đến?', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 6, 2, '崔浩', '大概三十分钟。', 'Dàgài sānshí fēnzhōng.', 'Khoảng ba mươi phút.', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 6, 3, '林娜', '我的袋子呢？', 'Wǒ de dàizi ne?', 'Túi của tôi đâu rồi?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 6, 3, '山田', '我把袋子放在桌子上了。', 'Wǒ bǎ dàizi fàng zài zhuōzi shàng le.', 'Tôi đã đặt túi của bạn lên bàn rồi.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 6, 3, '林娜', '谢谢你！', 'Xièxie nǐ!', 'Cảm ơn bạn!', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 7, 1, '阿明', '哪辆是你的自行车？', 'Nǎ liàng shì nǐ de zìxíngchē?', 'Chiếc nào là xe đạp của bạn?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 7, 1, '马丁', '我的自行车是红色的，有点儿旧了。', 'Wǒ de zìxíngchē shì hóngsè de, yǒudiǎnr jiù le.', 'Xe đạp của tôi màu đỏ, hơi cũ rồi.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 7, 2, '崔浩', '今年冬天变冷了，你觉得呢？', 'Jīnnián dōngtiān biàn lěng le, nǐ juéde ne?', 'Mùa đông năm nay lạnh hơn, bạn thấy sao?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 7, 2, '朱云', '是啊，比去年冷多了。', 'Shì a, bǐ qùnián lěng duō le.', 'Đúng vậy, lạnh hơn nhiều so với năm ngoái.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 7, 3, '林娜', '你怎么这么高兴？', 'Nǐ zěnme zhème gāoxìng?', 'Sao bạn vui vậy?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 7, 3, '朱云', '妈妈给我寄来了礼物，我很惊喜！', 'Māma gěi wǒ jìláile lǐwù, wǒ hěn jīngxǐ!', 'Mẹ gửi quà đến cho tôi, tôi rất bất ngờ!', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 8, 1, '山田', '对不起，我听不懂你说的话。', 'Duìbuqǐ, wǒ tīng bu dǒng nǐ shuō de huà.', 'Xin lỗi, tôi không hiểu bạn nói gì.', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 8, 1, '崔浩', '对不起，我说得太快了。我再说一遍。', 'Duìbuqǐ, wǒ shuō de tài kuài le. Wǒ zài shuō yí biàn.', 'Xin lỗi, tôi nói nhanh quá. Tôi nói lại lần nữa.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 8, 2, '马丁', '圣诞节快到了，你准备好了吗？', 'Shèngdànjié kuài dào le, nǐ zhǔnbèi hǎo le ma?', 'Giáng sinh sắp đến rồi, bạn chuẩn bị xong chưa?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 8, 2, '林娜', '还没有，我要去买礼物和卡片。', 'Hái méiyǒu, wǒ yào qù mǎi lǐwù hé kǎpiàn.', 'Chưa xong, tôi phải đi mua quà và thiệp.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 8, 3, '朱云', '你在做什么？', 'Nǐ zài zuò shénme?', 'Bạn đang làm gì đấy?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 8, 3, '阿明', '我正在看电视呢，这个节目很有意思。', 'Wǒ zhèngzài kàn diànshì ne, zhège jiémù hěn yǒuyìsi.', 'Tôi đang xem tivi, chương trình này rất thú vị.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 9, 1, '马丁', '长城有多长？', 'Chángchéng yǒu duō cháng?', 'Trường Thành dài bao nhiêu?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 9, 1, '李一民', '长城有八千八百五十多公里，是世界著名的古迹。', 'Chángchéng yǒu bāqiān bābǎi wǔshí duō gōnglǐ, shì shìjiè zhùmíng de gǔjì.', 'Trường Thành dài hơn 8850km, là di tích nổi tiếng thế giới.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 9, 2, '朱云', '昨天的晚会怎么样？', 'Zuótiān de wǎnhuì zěnmeyàng?', 'Buổi tiệc hôm qua thế nào?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 9, 2, '林娜', '晚会开得非常成功，大家都很开心。', 'Wǎnhuì kāi de fēicháng chénggōng, dàjiā dōu hěn kāixīn.', 'Buổi tiệc rất thành công, mọi người đều rất vui.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 9, 3, '李一民', '你以前做过什么工作？', 'Nǐ yǐqián zuòguo shénme gōngzuò?', 'Trước đây bạn từng làm công việc gì?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 9, 3, '马丁', '我当过英语老师，那段经历有意思极了。', 'Wǒ dāngguo Yīngyǔ lǎoshī, nà duàn jīnglì yǒuyìsi jíle.', 'Tôi từng là giáo viên tiếng Anh, trải nghiệm đó cực kỳ thú vị.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 10, 1, '阿明', '对不起，我迟到了。', 'Duìbuqǐ, wǒ chídào le.', 'Xin lỗi, tôi đến muộn rồi.', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 10, 1, '老师', '没关系，你要入乡随俗，每天早点儿起床。', 'Méi guānxi, nǐ yào rù xiāng suí sú, měitiān zǎodiǎnr qǐchuáng.', 'Không sao, em nên nhập gia tùy tục, mỗi ngày dậy sớm hơn.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 10, 1, '阿明', '好的，我以后一定定闹钟。', 'Hǎo de, wǒ yǐhòu yídìng dìng nàozhōng.', 'Vâng, sau này em nhất định sẽ đặt báo thức.', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 10, 2, '妈妈', '儿子明天就要回家了，我好激动！', 'Érzi míngtiān jiù yào huíjiā le, wǒ hǎo jīdòng!', 'Ngày mai con trai về nhà rồi, mẹ xúc động quá!', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 10, 2, '爸爸', '我明天去机场接他。', 'Wǒ míngtiān qù jīchǎng jiē tā.', 'Ngày mai tôi đi sân bay đón nó.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 10, 3, '顾客', '这辣椒新鲜吗？多少钱一斤？', 'Zhè làjiāo xīnxiān ma? Duōshao qián yì jīn?', 'Ớt này có tươi không? Bao nhiêu tiền một cân?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 10, 3, '卖辣椒的女孩儿', '很新鲜，三块钱一斤。', 'Hěn xīnxiān, sān kuài qián yì jīn.', 'Rất tươi, ba đồng một cân.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 11, 1, '朱云', '你为什么决定来中国留学？', 'Nǐ wèishénme juédìng lái Zhōngguó liúxué?', 'Vì sao bạn quyết định đến Trung Quốc du học?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 11, 1, '林娜', '其实，我和中国一直有个约会——这是我的梦想。', 'Qíshí, wǒ hé Zhōngguó yìzhí yǒu ge yuēhuì — zhè shì wǒ de mèngxiǎng.', 'Thực ra, tôi và Trung Quốc luôn có một cuộc hẹn — đó là ước mơ của tôi.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 11, 2, '马丁', '为什么我一个人站着吃？这里没有座位吗？', 'Wèishénme wǒ yí ge rén zhànzhe chī? Zhèlǐ méiyǒu zuòwèi ma?', 'Vì sao tôi phải đứng ăn một mình? Ở đây không có chỗ ngồi à?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 11, 2, '李一民', '今天人太多，座位都满了，这也是这儿的习俗。', 'Jīntiān rén tài duō, zuòwèi dōu mǎn le, zhè yě shì zhèr de xísú.', 'Hôm nay đông người quá, chỗ ngồi đầy hết rồi, đây cũng là phong tục ở đây.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 12, 1, '朱云', '听说你要去埃及？', 'Tīngshuō nǐ yào qù Āijí?', 'Nghe nói bạn sắp đi Ai Cập?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 12, 1, '马丁', '对，我一直想去看金字塔，这是我的旅行计划。', 'Duì, wǒ yìzhí xiǎng qù kàn jīnzìtǎ, zhè shì wǒ de lǚxíng jìhuà.', 'Đúng vậy, tôi luôn muốn đi xem kim tự tháp, đây là kế hoạch du lịch của tôi.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 12, 1, '朱云', '路上要小心一点儿。', 'Lùshang yào xiǎoxīn yìdiǎnr.', 'Trên đường phải cẩn thận nhé.', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 13, 1, '山田', '护士，我要一个枕头。', 'Hùshi, wǒ yào yí ge zhěntou.', 'Y tá ơi, tôi cần một cái gối.', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 13, 1, '护士', '什么？针头？您没生病要打针啊？', 'Shénme? Zhēntóu? Nín méi shēngbìng yào dǎzhēn a?', 'Gì cơ? Đầu kim? Ngài không ốm sao cần tiêm?', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 13, 1, '山田', '不是针头，是枕头，睡觉用的枕头！', 'Bú shì zhēntóu, shì zhěntou, shuìjiào yòng de zhěntou!', 'Không phải đầu kim, là cái gối, gối để ngủ ấy!', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 14, 1, '马丁', '师傅，去火车站多少钱？', 'Shīfu, qù huǒchēzhàn duōshao qián?', 'Bác tài ơi, đến ga tàu bao nhiêu tiền?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 14, 1, '司机', '大概三十块，不过现在堵车，可能要贵一点儿。', 'Dàgài sānshí kuài, búguò xiànzài dǔchē, kěnéng yào guì yìdiǎnr.', 'Khoảng ba mươi đồng, nhưng giờ tắc đường, có thể sẽ đắt hơn chút.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 14, 1, '马丁', '好的，麻烦您了。', 'Hǎo de, máfan nín le.', 'Vâng, phiền bác.', 2);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 15, 1, '朱云', '你怎么每次都这么准时？', 'Nǐ zěnme měicì dōu zhème zhǔnshí?', 'Sao lần nào bạn cũng đúng giờ vậy?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 15, 1, '崔浩', '我把表拨快了三分钟，这样就不会迟到了。', 'Wǒ bǎ biǎo bō kuàile sān fēnzhōng, zhèyàng jiù bú huì chídào le.', 'Tôi vặn đồng hồ nhanh lên ba phút, như vậy sẽ không đến muộn.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 15, 2, '林娜', '你到底来不来？我都等了半个小时了！', 'Nǐ dàodǐ lái bu lái? Wǒ dōu děngle bàn ge xiǎoshí le!', 'Rốt cuộc bạn có đến không? Tôi đợi nửa tiếng rồi đấy!', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 15, 2, '阿明', '对不起，尽管我很想早点儿到，却因为堵车迟到了。', 'Duìbuqǐ, jǐnguǎn wǒ hěn xiǎng zǎodiǎnr dào, què yīnwèi dǔchē chídào le.', 'Xin lỗi, mặc dù tôi rất muốn đến sớm, nhưng vì tắc đường nên đến muộn.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 17, 1, '山田', '坐公交车要带现金吗？', 'Zuò gōngjiāochē yào dài xiànjīn ma?', 'Đi xe buýt có cần mang tiền mặt không?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 17, 1, '朱云', '不必，只要有公交卡就能上车，很方便。', 'Búbì, zhǐyào yǒu gōngjiāokǎ jiù néng shàngchē, hěn fāngbiàn.', 'Không cần, chỉ cần có thẻ xe buýt là lên được, rất tiện.', 1);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 17, 2, '儿子', '爸爸，我们还要爬多久？', 'Bàba, wǒmen hái yào pá duōjiǔ?', 'Bố ơi, chúng ta còn phải leo bao lâu nữa?', 0);
INSERT INTO dialogue_lines (course_id, module_index, dialogue_group, speaker, zh, pinyin, vi, order_index) VALUES (12, 17, 2, '爸爸', '哪怕再累，我们也要爬到最高处，加油！', 'Nǎpà zài lèi, wǒmen yě yào pádào zuì gāo chù, jiāyóu!', 'Dù có mệt đến mấy, chúng ta cũng phải leo đến điểm cao nhất, cố lên!', 1);
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 0, '自我介绍', '我叫马丁，是美国人。我在中国学习汉语。我的老师姓李，我们常常说“你好”“您好”。今天我认识了新朋友朱云，她叫什么名字我一开始没听清楚，就又问了一遍。认识她我很高兴。', 'Wǒ jiào Mǎdīng, shì Měiguó rén. Wǒ zài Zhōngguó xuéxí Hànyǔ. Wǒ de lǎoshī xìng Lǐ, wǒmen chángcháng shuō "nǐ hǎo" "nín hǎo". Jīntiān wǒ rènshile xīn péngyou Zhūyún, tā jiào shénme míngzi wǒ yì kāishǐ méi tīng qīngchu, jiù yòu wènle yí biàn. Rènshi tā wǒ hěn gāoxìng.', 'Tôi tên là Martin, là người Mỹ. Tôi học tiếng Hán ở Trung Quốc. Thầy tôi họ Lý, chúng tôi thường nói "xin chào". Hôm nay tôi quen bạn mới Chu Vân, lúc đầu tôi nghe không rõ tên cô ấy nên hỏi lại. Quen được cô ấy tôi rất vui.');
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 1, '买东西和一家人', '阿明的法语不好，所以他学习汉语。他家有五口人：爸爸、妈妈、两个姐姐和他。周末，阿明去市场买香蕉，两块五一斤，他买了三斤，一共花了七块五。', 'Āmíng de Fǎyǔ bù hǎo, suǒyǐ tā xuéxí Hànyǔ. Tā jiā yǒu wǔ kǒu rén: bàba, māma, liǎng ge jiějie hé tā. Zhōumò, Āmíng qù shìchǎng mǎi xiāngjiāo, liǎng kuài wǔ yì jīn, tā mǎile sān jīn, yígòng huāle qī kuài wǔ.', 'Tiếng Pháp của A Minh không tốt, nên anh học tiếng Hán. Nhà anh có năm người: bố, mẹ, hai chị gái và anh. Cuối tuần, A Minh đi chợ mua chuối, hai đồng rưỡi một cân, anh mua ba cân, tổng cộng hết bảy đồng rưỡi.');
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 2, '银行、日期和安排', '中国银行在学校前边，医院旁边。今天九月三号，星期五。林娜今天上午上课，下午要去银行，可是银行的人说星期天不开门。她说：“没关系，星期天我不忙，可以休息一下。”', 'Zhōngguó Yínháng zài xuéxiào qiánbian, yīyuàn pángbiān. Jīntiān jiǔyuè sān hào, xīngqīwǔ. Línnà jīntiān shàngwǔ shàngkè, xiàwǔ yào qù yínháng, kěshì yínháng de rén shuō xīngqītiān bù kāimén. Tā shuō: "Méi guānxi, xīngqītiān wǒ bù máng, kěyǐ xiūxi yíxià."', 'Ngân hàng Trung Quốc ở trước trường, cạnh bệnh viện. Hôm nay ngày 3 tháng 9, thứ sáu. Linna sáng nay học, chiều định đi ngân hàng, nhưng nhân viên nói chủ nhật không mở cửa. Cô nói: "Không sao, chủ nhật tôi không bận, có thể nghỉ ngơi."');
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 3, '周末、食堂和咖啡', '这个星期天崔浩不忙，他想休息一下，也想和朋友一起运动。中午他在学校食堂吃饭，食堂的菜很好吃。吃完饭，他去咖啡店，要了一杯咖啡，服务员问他要不要加糖，他说不用。', 'Zhège xīngqītiān Cuī Hào bù máng, tā xiǎng xiūxi yíxià, yě xiǎng hé péngyou yìqǐ yùndòng. Zhōngwǔ tā zài xuéxiào shítáng chīfàn, shítáng de cài hěn hǎochī. Chīwán fàn, tā qù kāfēidiàn, yàole yì bēi kāfēi, fúwùyuán wèn tā yào bu yào jiā táng, tā shuō búyòng.', 'Chủ nhật này Thôi Hạo không bận, anh muốn nghỉ ngơi, cũng muốn cùng bạn vận động. Trưa anh ăn ở căng tin trường, món ăn rất ngon. Ăn xong, anh đi quán cà phê, gọi một cốc cà phê, phục vụ hỏi có thêm đường không, anh nói không cần.');
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 4, '搬家、毛衣和打工', '崔浩已经搬家了，新房子很大也很新。上个星期他买了一件红色的毛衣，很喜欢。他是大学生，问老师大学生可以不可以打工，老师说可以，但是不能影响学习。崔浩决定周末去公司打工赚钱。', 'Cuī Hào yǐjīng bānjiā le, xīn fángzi hěn dà yě hěn xīn. Shàng ge xīngqī tā mǎile yí jiàn hóngsè de máoyī, hěn xǐhuan. Tā shì dàxuéshēng, wèn lǎoshī dàxuéshēng kěyǐ bu kěyǐ dǎgōng, lǎoshī shuō kěyǐ, dànshì bù néng yǐngxiǎng xuéxí. Cuī Hào juédìng zhōumò qù gōngsī dǎgōng zhuànqián.', 'Thôi Hạo đã chuyển nhà, nhà mới rất to và mới. Tuần trước anh mua một áo len đỏ, rất thích. Anh là sinh viên, hỏi thầy sinh viên có được làm thêm không, thầy nói được nhưng không được ảnh hưởng học tập. Thôi Hạo quyết định cuối tuần đi làm thêm kiếm tiền.');
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 5, '礼物、口语和上网', '今天是马丁的生日，阿明想送他礼物，送蛋糕还是巧克力呢？朱云说自己口语和听力都很好，但是阅读不太好。崔浩昨天上了四个小时的网，眼睛很累，朋友都叫他多休息。', 'Jīntiān shì Mǎdīng de shēngrì, Āmíng xiǎng sòng tā lǐwù, sòng dàngāo háishi qiǎokèlì ne? Zhūyún shuō zìjǐ kǒuyǔ hé tīnglì dōu hěn hǎo, dànshì yuèdú bú tài hǎo. Cuī Hào zuótiān shàngle sì ge xiǎoshí de wǎng, yǎnjing hěn lèi, péngyou dōu jiào tā duō xiūxi.', 'Hôm nay là sinh nhật Martin, A Minh muốn tặng quà, tặng bánh kem hay sô-cô-la đây? Chu Vân nói nói và nghe của mình đều tốt, nhưng đọc hiểu không tốt lắm. Thôi Hạo hôm qua lên mạng bốn tiếng, mắt rất mỏi, bạn bè bảo anh nghỉ ngơi nhiều hơn.');
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 6, '暖气、外卖和东西', '林娜家的暖气坏了，还没修好，房间很冷，她只好去图书馆学习。晚上大家点了外卖，快餐可以送到家里，又方便又快。林娜把袋子放在桌子上，袋子里有她的自行车钥匙。', 'Línnà jiā de nuǎnqì huài le, hái méi xiūhǎo, fángjiān hěn lěng, tā zhǐhǎo qù túshūguǎn xuéxí. Wǎnshang dàjiā diǎnle wàimài, kuàicān kěyǐ sòngdào jiā lǐ, yòu fāngbiàn yòu kuài. Línnà bǎ dàizi fàng zài zhuōzi shàng, dàizi lǐ yǒu tā de zìxíngchē yàoshi.', 'Lò sưởi nhà Linna hỏng, vẫn chưa sửa, phòng rất lạnh, cô đành đi thư viện học. Tối mọi người gọi đồ ăn giao hàng, đồ ăn nhanh giao tận nhà, vừa tiện vừa nhanh. Linna đặt túi lên bàn, trong túi có chìa khóa xe đạp của cô.');
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 7, '颜色、天气和礼物', '林娜的自行车是红色的，有点儿旧了。今年冬天变冷了，跟去年差不多冷。上星期，林娜的妈妈给她寄来了礼物，打开的时候她很惊喜，因为里面有她一直想要的东西。', 'Línnà de zìxíngchē shì hóngsè de, yǒudiǎnr jiù le. Jīnnián dōngtiān biàn lěng le, gēn qùnián chàbuduō lěng. Shàng xīngqī, Línnà de māma gěi tā jìláile lǐwù, dǎkāi de shíhou tā hěn jīngxǐ, yīnwèi lǐmiàn yǒu tā yìzhí xiǎng yào de dōngxi.', 'Xe đạp của Linna màu đỏ, hơi cũ rồi. Mùa đông năm nay lạnh hơn, gần bằng năm ngoái. Tuần trước, mẹ Linna gửi quà cho cô, lúc mở ra cô rất bất ngờ, vì bên trong có thứ cô luôn muốn có.');
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 8, '听不懂、圣诞节和电视', '山田说他有时候听不懂中国朋友说的话，虽然他很努力学习。圣诞节快到了，大家都在准备礼物，气氛很热闹。晚上山田正在看电视，节目里正在介绍中国文化，他觉得很有意思。', 'Shāntián shuō tā yǒushíhou tīng bu dǒng Zhōngguó péngyou shuō de huà, suīrán tā hěn nǔlì xuéxí. Shèngdànjié kuài dào le, dàjiā dōu zài zhǔnbèi lǐwù, qìfēn hěn rènao. Wǎnshang Shāntián zhèngzài kàn diànshì, jiémù lǐ zhèngzài jièshào Zhōngguó wénhuà, tā juéde hěn yǒuyìsi.', 'Yamada nói đôi khi anh không hiểu bạn Trung Quốc nói gì, dù anh học rất chăm chỉ. Giáng sinh sắp đến, mọi người đang chuẩn bị quà, không khí náo nhiệt. Tối Yamada đang xem tivi, chương trình đang giới thiệu văn hóa Trung Quốc, anh thấy rất thú vị.');
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 9, '长城、晚会和经历', '长城有八千八百五十多公里，是世界著名的历史古迹，山田很想去看看。上个星期学校开了晚会，开得非常成功，大家唱歌跳舞很开心。马丁说他以前当过英语老师，那段经历有意思极了。', 'Chángchéng yǒu bāqiān bābǎi wǔshí duō gōnglǐ, shì shìjiè zhùmíng de lìshǐ gǔjì, Shāntián hěn xiǎng qù kànkan. Shàng ge xīngqī xuéxiào kāile wǎnhuì, kāi de fēicháng chénggōng, dàjiā chànggē tiàowǔ hěn kāixīn. Mǎdīng shuō tā yǐqián dāngguo Yīngyǔ lǎoshī, nà duàn jīnglì yǒuyìsi jíle.', 'Trường Thành dài hơn 8850km, là di tích lịch sử nổi tiếng thế giới, Yamada rất muốn đi xem. Tuần trước trường tổ chức tiệc, rất thành công, mọi người hát múa rất vui. Martin nói trước đây anh từng là giáo viên tiếng Anh, trải nghiệm đó cực kỳ thú vị.');
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 10, '入乡随俗', '阿明第一次到中国时常常迟到，后来渐渐习惯了这里的生活，明白了“入乡随俗”的道理。他的朋友说，儿子要回家时，妈妈会很激动。市场上有个卖辣椒的女孩儿，她既聪明又勤劳，生意很好。', 'Āmíng dì-yī cì dào Zhōngguó shí chángcháng chídào, hòulái jiànjiàn xíguànle zhèlǐ de shēnghuó, míngbáile "rù xiāng suí sú" de dàolǐ. Tā de péngyou shuō, érzi yào huíjiā shí, māma huì hěn jīdòng. Shìchǎng shàng yǒu ge mài làjiāo de nǚháir, tā jì cōngming yòu qínláo, shēngyi hěn hǎo.', 'Lần đầu A Minh đến Trung Quốc thường hay muộn giờ, sau đó dần quen với cuộc sống ở đây, hiểu ra đạo lý "nhập gia tùy tục". Bạn anh nói, khi con trai sắp về nhà, mẹ sẽ rất xúc động. Ở chợ có cô gái bán ớt, vừa thông minh vừa chăm chỉ, buôn bán rất tốt.');
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 11, '约会和一个人吃饭', '林娜说她和中国一直有个约会，这是她的梦想，她终于决定来中国留学。可是第一天她要一个人站着吃饭，因为那天人太多，座位都满了，这也是这儿的习俗。', 'Línnà shuō tā hé Zhōngguó yìzhí yǒu ge yuēhuì, zhè shì tā de mèngxiǎng, tā zhōngyú juédìng lái Zhōngguó liúxué. Kěshì dì-yī tiān tā yào yí ge rén zhànzhe chīfàn, yīnwèi nà tiān rén tài duō, zuòwèi dōu mǎn le, zhè yě shì zhèr de xísú.', 'Linna nói cô và Trung Quốc luôn có một cuộc hẹn, đó là ước mơ của cô, cuối cùng cô quyết định đến Trung Quốc du học. Nhưng ngày đầu cô phải đứng ăn một mình, vì hôm đó đông người, hết chỗ ngồi, đây cũng là phong tục ở đây.');
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 12, '梦想、旧梦和爱的教育', '马丁一直想去埃及看金字塔，这是他的旅行计划。老师讲了一个旧梦的故事：一个人回到故乡，发现变化比想的还大。老师还说，爱的教育比严格的教育更有效，对学生要有耐心。', 'Mǎdīng yìzhí xiǎng qù Āijí kàn jīnzìtǎ, zhè shì tā de lǚxíng jìhuà. Lǎoshī jiǎngle yí ge jiùmèng de gùshi: yí ge rén huídào gùxiāng, fāxiàn biànhuà bǐ xiǎng de hái dà. Lǎoshī hái shuō, ài de jiàoyù bǐ yángé de jiàoyù gèng yǒuxiào, duì xuésheng yào yǒu nàixīn.', 'Martin luôn muốn đi Ai Cập xem kim tự tháp, đó là kế hoạch du lịch của anh. Thầy kể một câu chuyện giấc mơ cũ: một người về quê, phát hiện thay đổi lớn hơn nghĩ. Thầy còn nói, giáo dục bằng tình thương hiệu quả hơn giáo dục nghiêm khắc, cần kiên nhẫn với học sinh.');
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 13, '快乐很简单和两个小故事', '快乐其实很简单，学会知足，珍惜拥有的一切，就会更快乐。书本里有一只小蚂蚁，一个学生好奇地观察它，发现小小的蚂蚁也有自己的世界。还有一个学生把“枕头”说成了“针头”，闹了大笑话。', 'Kuàilè qíshí hěn jiǎndān, xuéhuì zhīzú, zhēnxī yōngyǒu de yíqiè, jiù huì gèng kuàilè. Shūběn lǐ yǒu yì zhī xiǎo mǎyǐ, yí ge xuésheng hàoqí de guānchá tā, fāxiàn xiǎoxiǎo de mǎyǐ yě yǒu zìjǐ de shìjiè. Hái yǒu yí ge xuésheng bǎ "zhěntou" shuōchéngle "zhēntóu", nàole dà xiàohua.', 'Hạnh phúc thực ra rất đơn giản, học biết đủ, trân trọng những gì có, sẽ hạnh phúc hơn. Trong sách có một con kiến nhỏ, một học sinh tò mò quan sát nó, phát hiện con kiến nhỏ cũng có thế giới riêng. Còn có một học sinh nói nhầm "gối" thành "đầu kim", gây trận cười lớn.');
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 14, '来信、打的和信鸽', '一位学生说，中国来信改变了她的生活，除了学习汉语，她还通过写信了解了中国文化。另一位学生第一次打的，路上堵车，但幸好司机走的路线很安全。还有一只信鸽飞了很远才回来，真是奇迹。', 'Yí wèi xuésheng shuō, Zhōngguó láixìn gǎibiànle tā de shēnghuó, chúle xuéxí Hànyǔ, tā hái tōngguò xiěxìn liǎojiěle Zhōngguó wénhuà. Lìng yí wèi xuésheng dì-yī cì dǎdī, lùshang dǔchē, dàn xìnghǎo sījī zǒu de lùxiàn hěn ānquán. Hái yǒu yì zhī xìngē fēile hěn yuǎn cái huílái, zhēnshi qíjì.', 'Một học sinh nói, lá thư từ Trung Quốc thay đổi cuộc đời cô, ngoài học tiếng Hán, cô còn hiểu văn hóa Trung Quốc qua viết thư. Học sinh khác lần đầu đi taxi, đường tắc, nhưng may tài xế đi tuyến an toàn. Còn có chim bồ câu bay rất xa mới về, thật là kỳ tích.');
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 15, '准时、约会和电影', '崔浩每次都很准时，因为他把表拨快了三分钟。林娜和阿明约好六点见面，尽管阿明因为堵车迟到了，林娜还是等了他。有位盲人朋友，即使看不见画面，也能靠声音“看”电影，想象出情节。', 'Cuī Hào měicì dōu hěn zhǔnshí, yīnwèi tā bǎ biǎo bō kuàile sān fēnzhōng. Línnà hé Āmíng yuēhǎo liù diǎn jiànmiàn, jǐnguǎn Āmíng yīnwèi dǔchē chídào le, Línnà háishi děngle tā. Yǒu wèi mángrén péngyou, jíshǐ kàn bu jiàn huàmiàn, yě néng kào shēngyīn "kàn" diànyǐng, xiǎngxiàng chū qíngjié.', 'Thôi Hạo lần nào cũng đúng giờ, vì vặn đồng hồ nhanh ba phút. Linna và A Minh hẹn sáu giờ gặp nhau, dù A Minh tắc đường đến muộn, Linna vẫn đợi anh. Có người bạn khiếm thị, dù không nhìn thấy hình, vẫn có thể "xem" phim bằng âm thanh, tưởng tượng ra tình tiết.');
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 16, '笔友、人格和愚公', '山田有个中国笔友，他们常常写信交流，坚持写信才能保持这段珍贵的友谊。老师说，每个人都应该受到尊重，不要小看自己。愚公决心把大山移走，不管别人怎么笑话他，都不放弃，最后成功了。', 'Shāntián yǒu ge Zhōngguó bǐyǒu, tāmen chángcháng xiěxìn jiāoliú, jiānchí xiěxìn cái néng bǎochí zhè duàn zhēnguì de yǒuyì. Lǎoshī shuō, měi ge rén dōu yīnggāi shòudào zūnzhòng, búyào xiǎokàn zìjǐ. Yúgōng juéxīn bǎ dàshān yízǒu, bùguǎn biéren zěnme xiàohua tā, dōu bú fàngqì, zuìhòu chénggōng le.', 'Yamada có bạn qua thư Trung Quốc, họ thường viết thư trao đổi, kiên trì viết thư mới giữ được tình bạn quý báu. Thầy nói, mỗi người đều nên được tôn trọng, đừng xem thường bản thân. Ngu Công quyết dời núi lớn, bất kể người khác cười nhạo, không bỏ cuộc, cuối cùng thành công.');
INSERT INTO reading_passages (course_id, module_index, title, content_zh, content_pinyin, content_vi) VALUES (12, 17, '卡、低碳生活和长城', '现在用卡很方便，不必带很多现金。有人一直坚持“低碳生活”，骑车上班，垃圾分类。有对父子一起爬长城，哪怕很累，父亲也坚持陪儿子爬到最高处。还有个年轻人搭车去柏林，一路遇到很多善良的人。', 'Xiànzài yòng kǎ hěn fāngbiàn, búbì dài hěn duō xiànjīn. Yǒu rén yìzhí jiānchí "dītàn shēnghuó", qíchē shàngbān, lājī fēnlèi. Yǒu duì fùzǐ yìqǐ pá Chángchéng, nǎpà hěn lèi, fùqīn yě jiānchí péi érzi pádào zuì gāo chù. Hái yǒu ge niánqīngrén dāchē qù Bólín, yílù yùdào hěn duō shànliáng de rén.', 'Bây giờ dùng thẻ rất tiện, không cần mang nhiều tiền mặt. Có người luôn kiên trì "sống ít carbon", đi xe đạp đi làm, phân loại rác. Có cặp cha con cùng leo Trường Thành, dù mệt, cha vẫn kiên trì cùng con leo đến đỉnh. Còn có chàng trai đi nhờ xe đến Berlin, trên đường gặp nhiều người tốt bụng.');
